     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    17→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    18→
    19→    ADJUST {
    20→        $graph = Chalk::IR::Graph->new();
    21→        $scope = Chalk::IR::Scope->new();
    22→    }
    23→
    24→    # Generate unique node ID
    25→    method next_node_id() {
    26→        my $id = "node_$node_counter";
    27→        $node_counter++;
    28→        return $id;
    29→    }
    30→
    31→    # Set current control flow node
    32→    method set_control($ctrl) {
    33→        $current_control = $ctrl;
    34→    }
    35→
    36→    # Create Start node for a function/method
    37→    method build_start_node($function_name = 'main', $params = undef) {
    38→        $params //= [];
    39→        my $node_id = $self->next_node_id();
    40→        my $empty_inputs = [];
    41→        my $attributes = { function => $function_name, params => $params };
    42→        my $start = Chalk::IR::Node->new(
    43→            id => $node_id,
    44→            op => 'Start',
    45→            inputs => $empty_inputs,
    46→            attributes => $attributes
    47→        );
    48→        $graph->add_node($start);
    49→        $self->set_control($start->id);
    50→
    51→        # Create Proj nodes for each parameter and register in scope
    52→        my $param_count = scalar($params->@*);
    53→        for my $i (0..($param_count - 1)) {
    54→            my $param_name = $params->[$i];
    55→            my $proj = $self->build_proj_node($start, $i, $param_name);
    56→            # Register parameter Proj in scope so lookups return it directly
    57→            $scope->define($param_name, $proj->id);
    58→        }
    59→
    60→        return $start;
    61→    }
    62→
    63→    # Create Constant node
    64→    method build_constant_node($value, $type = 'Int') {
    65→        my $node_id = $self->next_node_id();
    66→        my $attributes = { value => $value, type => $type };
    67→        my $constant = Chalk::IR::Node->new(
    68→            id => $node_id,
    69→            op => 'Constant',
    70→            inputs => [$current_control],
    71→            attributes => $attributes
    72→        );
    73→        $graph->add_node($constant);
    74→        return $constant;
    75→    }
    76→
    77→    # Create Return node
    78→    # If $control is undef, uses current_control. Otherwise uses provided control.
    79→    method build_return_node($value_node, $control = undef) {
    80→        # Debug: check what we received
    81→        my $ref_type = ref($value_node) || 'SCALAR';
    82→        my $prefix = substr($ref_type, 0, 15);
    83→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
    84→        unless ($ref_type && $is_node) {
    85→            warn "build_return_node received non-node: $ref_type\n";
    86→            return undef;
    87→        }
    88→
    89→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    90→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    91→
    92→        my $node_id = $self->next_node_id();
    93→        my $empty_attrs = {};
    94→        my $return = Chalk::IR::Node->new(
    95→            id => $node_id,
    96→            op => 'Return',
    97→            inputs => [$ctrl, $value_node->id],
    98→            attributes => $empty_attrs
    99→        );
   100→        $graph->add_node($return);

