#!/usr/bin/env perl
# ABOUTME: Integration test for complete Sea of Nodes IR generation across lib/Chalk/
# ABOUTME: Tests --generate-ir flag and validates IR generation for all Chalk modules
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Test::More;
use File::Temp qw(tempdir);
use Cwd qw(abs_path);

# Test 1: --generate-ir flag exists and produces output
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;
    my $exit_code = $? >> 8;

    ok($output, '--generate-ir flag produces output');
    # Exit code should be 0 if successful, or 1 if there are failures
    ok($exit_code == 0 || $exit_code == 1, '--generate-ir exits with valid code');
    like($output, qr/IR generation/i, 'Output mentions IR generation');
}

# Test 2: --generate-ir discovers all lib/Chalk/ modules
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;

    # Should find key modules
    like($output, qr/Chalk::IR::Node/i, 'Discovers Chalk::IR::Node');
    like($output, qr/Chalk::IR::Graph/i, 'Discovers Chalk::IR::Graph');
    like($output, qr/Chalk::IR::Builder/i, 'Discovers Chalk::IR::Builder');
}

# Test 3: --generate-ir generates valid IR for each module
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;

    # Should show IR generation for modules
    like($output, qr/Generating IR|Generated IR/i, 'Shows IR generation progress');
}

# Test 4: --generate-ir validates all generated IR
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;

    # Should show validation results
    like($output, qr/Validat/i, 'Shows validation progress');
}

# Test 5: --generate-ir produces summary statistics
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;

    # Should show summary with counts
    like($output, qr/Total|Summary/i, 'Shows summary statistics');
    like($output, qr/Success|Passed/i, 'Shows success count');
}

# Test 6: --generate-ir with --output-format json produces JSON output
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir --output-format json 2>&1`;
    my $exit_code = $? >> 8;

    # Should produce JSON output for at least one module
    ok($output =~ /"nodes"/ || $output =~ /JSON/i, 'Produces JSON output with --output-format json');
}

# Test 7: IR generation handles all Chalk language features
{
    # Ensure we can generate IR for modules using advanced features
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;

    # Check that we handle modules with classes, arrays, hashes, etc.
    # These modules use advanced features from phases 1-5
    like($output, qr/Chalk::IR::Builder|Chalk::IR::Graph/,
         'Handles modules with class support');
}

# Test 8: All generated IR validates successfully
{
    my $output = `PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1`;
    my $exit_code = $? >> 8;

    # If there are validation failures, they should be reported
    if ($exit_code != 0) {
        unlike($output, qr/validation failed|invalid IR/i,
               'No validation failures reported (or explicitly marked as TODO)');
    } else {
        like($output, qr/validation.*success|all.*valid/i,
             'All IR validates successfully');
    }
}

done_testing();

