#!/usr/bin/env perl
# ABOUTME: Integration test for complete Sea of Nodes IR generation framework
# ABOUTME: Tests --generate-ir flag infrastructure and module discovery for lib/Chalk/
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Test::More;

# NOTE: Full IR generation for all 59 modules would take very long (several minutes).
# These tests focus on validating the infrastructure is in place, using a small sample.

# Test 1: --generate-ir flag exists and accepts the option
{
    # Use echo to create empty input, so it doesn't hang waiting for stdin
    my $output = `echo "" | PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1 | head -10`;

    ok($output, '--generate-ir flag produces output');
    like($output, qr/Sea of Nodes IR Generation|IR Generation/i, 'Output mentions IR generation');
}

# Test 2: --generate-ir discovers modules in lib/Chalk/
{
    my $output = `echo "" | PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir 2>&1 | head -20`;

    # Should discover modules
    like($output, qr/Discovered \d+ modules/i, 'Reports discovered module count');
    like($output, qr/Chalk::/i, 'Output mentions Chalk:: modules');
}

# Test 3: --output-format flag is recognized
{
    my $output = `echo "" | PLENV_VERSION=5.42.0 plenv exec perl app.pl --generate-ir --output-format json 2>&1 | head -10`;

    ok($output, '--output-format flag is accepted');
    like($output, qr/Sea of Nodes IR Generation|IR Generation/i, '--output-format does not break --generate-ir');
}

# Test 4: Infrastructure components are loadable
{
    # Test that the required modules can be loaded
    use_ok('Chalk::ImportResolver');
    use_ok('Chalk::IR::Builder');
    use_ok('Chalk::IR::Validator');
}

# Test 5: ImportResolver can discover Chalk modules
{
    use lib 'tools';
    use Chalk::ImportResolver;

    my $resolver = Chalk::ImportResolver->new();
    ok($resolver, 'ImportResolver instantiates');

    my $path = $resolver->module_to_path('Chalk::IR::Node');
    is($path, 'lib/Chalk/IR/Node.pm', 'module_to_path converts correctly');

    ok(-f $path, 'Converted path points to existing file');
}

# Test 6: IR Builder and Validator work together
{
    use Chalk::IR::Builder;
    use Chalk::IR::Validator;

    my $builder = Chalk::IR::Builder->new();
    my $validator = Chalk::IR::Validator->new();

    ok($builder, 'IR Builder instantiates');
    ok($validator, 'IR Validator instantiates');

    my $graph = $builder->graph;
    ok($graph, 'Builder has a graph');
}

done_testing();

