            $failure_count++;
            next;
        };
        local $/;
        my $content = <$fh>;
        close $fh;

        # Parse the module
        print("Parsing $module ($file_path)... ");
        my $result = $parser->parse_string($content);

        if ($result) {
            print("OK\n");
            $success_count++;
        } else {
            print("FAILED\n");
            $failure_count++;
        }
    }

    print("\nModule compilation summary:\n");
