     1→# ABOUTME: Semantic semiring for building values during parsing with evaluation contexts
     2→# ABOUTME: Tracks contexts and enables semantic actions via EvalContext comonad
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use Chalk::Base;
     8→use Chalk::EvalContext;
     9→
    10→class Chalk::Semiring::SemanticElement :isa(Chalk::Element) {
    11→    field $value :param :reader;         # Computed semantic value
    12→    field $context :param :reader;       # Evaluation context
    13→    field $sppf_node :param = undef;     # Optional SPPF node
    14→
    15→    method add( $other, $swap = undef ) {
    16→        # For alternatives (choice), prefer non-zero value
    17→        # If self has value 0 (is add_id), return other
    18→        if ($value == 0) {
    19→            return $other;
    20→        }
    21→
    22→        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
    23→        # This handles the case where we update the chart after evaluation
    24→        my $self_focus = $self->context->focus;
    25→        my $other_focus = $other->context->focus;
    26→
    27→        if (!defined($self_focus) && defined($other_focus)) {
    28→            return $other;
    29→        }
    30→        if (defined($self_focus) && !defined($other_focus)) {
    31→            return $self;
    32→        }
    33→
    34→        # For semantic values, prefer the alternative that consumed more input
    35→        # (this handles ambiguous parses - longer parse is more complete)
    36→        # Use parse span (end_pos - start_pos) as primary ranking
    37→        my $self_span = $self->context->end_pos - $self->context->start_pos;
    38→        my $other_span = $other->context->end_pos - $other->context->start_pos;
    39→
    40→        if ($other_span > $self_span) {
    41→            return $other;  # Other consumed more input, prefer it
    42→        }
    43→        if ($self_span > $other_span) {
    44→            return $self;  # Self consumed more input, prefer it
    45→        }
    46→
    47→        # If spans are equal, prefer the alternative with more children
    48→        # (handles cases where both consumed same input but one has more structure)
    49→        my $self_children = scalar(@{$self->context->children});
    50→        my $other_children = scalar(@{$other->context->children});
    51→
    52→        if ($other_children > $self_children) {
    53→            return $other;
