   428→    method generate_loop_phi_nodes($loop_node) {
   429→        # Generate phi nodes for all variables modified within the loop
   430→        return {} unless $loop_tracking_active;
   431→        return {} unless defined $loop_entry_scope;
   432→
   433→        # Capture current (loop-end) values before creating phis
   434→        my $loop_end_scope = $scope->snapshot_bindings();
   435→
   436→        # Find which variables were modified in the loop
   437→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   438→
   439→        # Generate a phi node for each modified variable
   440→        my %phis = ();
   441→        for my $var (@modified_vars) {
   442→            my $initial_value = $loop_entry_scope->{$var};
   443→            my $loop_value = $loop_end_scope->{$var};
   444→
   445→            # Create phi with initial value; backedge added later
   446→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   447→            $phis{$var} = $phi;
   448→
   449→            # Update scope to use phi node for this variable
   450→            # This ensures uses after the loop see the phi
   451→            $scope->define($var, $phi->id);
   452→        }
   453→
   454→        return \%phis;
   455→    }
