   598→        # Create ArraySet node for setting array element by index
   599→        my $array_ref = { op => 'NodeRef', node_id => $array_node->id };
   600→        my $index_ref = { op => 'NodeRef', node_id => $index_node->id };
   601→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
