            return 1 if $left > 0 && $right < 0 && $left > $max_int + $right;
            return 1 if $left < 0 && $right > 0 && $left < $min_int + $right;
        }
        elsif ($op eq 'Multiply') {
            return 1 if $left != 0 && abs($right) > abs($max_int / $left);
