class Chalk::Semiring::Semantic {
    field $grammar :param;      # The grammar used for parsing
    field $env :param = {};     # Environment hash passed to evaluation contexts
    field $forest :reader;      # SPPFForest for parse forest representation
    field $mul_id;              # Multiplicative identity element
    field $add_id;              # Additive identity element
    field $derivation_counter = 0;  # Counter for unique derivation IDs

    ADJUST {
        $forest = Chalk::IR::SPPF::SPPFForest->new();

        # Create the identity elements
        my $empty_ctx_mul = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => 0,
            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef,
            forest => $forest
        );

        my $empty_ctx_add = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => 0,
            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef,
            forest => $forest
        );

        $mul_id = Chalk::Semiring::SemanticElement->new(
            value => 1,  # mul_id has value 1
            context => $empty_ctx_mul
        );

        $add_id = Chalk::Semiring::SemanticElement->new(
            value => 0,  # add_id has value 0 (failure/no parse)
            context => $empty_ctx_add
        );
    }

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
        # Generate unique derivation ID for this parse alternative
        my $derivation_id = "deriv_$derivation_counter";
        $derivation_counter++;

        # Add derivation_id to env so semantic actions can access it
        my %extended_env = %$env;
        $extended_env{derivation_id} = $derivation_id;

        my $ctx = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => \%extended_env,
            grammar => $grammar,
            rule => $rule,
            forest => $forest
        );

        return Chalk::Semiring::SemanticElement->new(
            value => 1,  # Success value (not add_id which is 0)
            context => $ctx
        );
    }

