    method build_if_true_node($if_node) {
        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
        return $if_true;
    }

    method build_if_false_node($if_node) {
        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
