   721→        my $node_id = $self->next_node_id();
   722→        my $hash_keys = Chalk::IR::Node->new(
   723→            id => $node_id,
   724→            op => 'HashKeys',
   725→            inputs => [$current_control, $hash_node->id],
   726→            attributes => $attributes
   727→        );
   728→        $graph->add_node($hash_keys);
   729→        return $hash_keys;
   730→    }
   731→
   732→    # String operations (Issue #98 Phase 4)
   733→    method build_str_concat_node($left_node, $right_node) {
   734→        # Create StrConcat node for concatenating two strings
   735→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   736→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   737→
   738→        my $attributes = {
   739→            left => $left_ref,
   740→            right => $right_ref
   741→        };
   742→
