   744→        my $str_concat = Chalk::IR::Node->new(
   745→            id => $node_id,
   746→            op => 'StrConcat',
   747→            inputs => [$current_control, $left_node->id, $right_node->id],
   748→            attributes => $attributes
   749→        );
   750→        $graph->add_node($str_concat);
   751→        return $str_concat;
   752→    }
   753→
   754→    method build_str_length_node($string_node) {
   755→        # Create StrLength node for getting string length
   756→        my $string_ref = { op => 'NodeRef', node_id => $string_node->id };
   757→
   758→        my $attributes = {
   759→            string => $string_ref
   760→        };
   761→
   762→        my $node_id = $self->next_node_id();
   763→        my $str_length = Chalk::IR::Node->new(
   764→            id => $node_id,
   765→            op => 'StrLength',
   766→            inputs => [$current_control, $string_node->id],
   767→            attributes => $attributes
   768→        );
   769→        $graph->add_node($str_length);
   770→        return $str_length;
   771→    }
   772→
   773→    method build_str_substr_node($string_node, $offset_node, $length_node) {
   774→        # Create StrSubstr node for extracting substring
   775→        my $string_ref = { op => 'NodeRef', node_id => $string_node->id };
   776→        my $offset_ref = { op => 'NodeRef', node_id => $offset_node->id };
   777→        my $length_ref = { op => 'NodeRef', node_id => $length_node->id };
