   785→        my $node_id = $self->next_node_id();
   786→        my $str_substr = Chalk::IR::Node->new(
   787→            id => $node_id,
   788→            op => 'StrSubstr',
   789→            inputs => [$current_control, $string_node->id, $offset_node->id, $length_node->id],
   790→            attributes => $attributes
