   796→    # Module system support (Issue #98 Phase 5)
   797→    method build_use_statement_node($type, $module, $imports) {
   798→        # Create UseStatement node for capturing use statement metadata
   799→        # $type: 'version', 'pragma', 'module', or 'external'
   800→        # $module: module name (e.g., '5.42.0', 'experimental', 'Chalk::IR::Node')
