     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→    field $current_derivation_id :reader;  # Current derivation ID for tagging nodes
    17→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    18→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    19→
    20→    ADJUST {
    21→        $graph = Chalk::IR::Graph->new();
    22→        $scope = Chalk::IR::Scope->new();
    23→    }
    24→
    25→    # Generate unique node ID
    26→    method next_node_id() {
    27→        my $id = "node_$node_counter";
    28→        $node_counter++;
    29→        return $id;
    30→    }
    31→
    32→    # Set current control flow node
    33→    method set_control($ctrl) {
    34→        $current_control = $ctrl;
    35→    }
    36→
    37→    # Set current derivation ID for tagging nodes
    38→    method set_derivation_id($deriv_id) {
    39→        $current_derivation_id = $deriv_id;
    40→    }
    41→
    42→    # Create Start node for a function/method
    43→    method build_start_node($function_name = 'main', $params = undef) {
    44→        $params //= [];
    45→        my $node_id = $self->next_node_id();
    46→        my $empty_inputs = [];
    47→        my $attributes = { function => $function_name, params => $params };
    48→        my $start = Chalk::IR::Node->new(
    49→            id            => $node_id,
    50→            op            => 'Start',
    51→            inputs        => $empty_inputs,
    52→            attributes    => $attributes,
    53→            derivation_id => $current_derivation_id,
    54→        );
    55→        $graph->add_node($start);
    56→        $self->set_control($start->id);
    57→
    58→        # Create Proj nodes for each parameter and register in scope
    59→        my $param_count = scalar($params->@*);
    60→        for my $i (0..($param_count - 1)) {
    61→            my $param_name = $params->[$i];
    62→            my $proj = $self->build_proj_node($start, $i, $param_name);
    63→            # Register parameter Proj in scope so lookups return it directly
    64→            $scope->define($param_name, $proj->id);
    65→        }
    66→
    67→        return $start;
    68→    }
    69→
    70→    # Create Constant node
    71→    method build_constant_node($value, $type = 'Int') {
    72→        my $node_id = $self->next_node_id();
    73→        my $attributes = { value => $value, type => $type };
    74→        my $constant = Chalk::IR::Node->new(
    75→            id => $node_id,
    76→            op => 'Constant',
    77→            inputs => [$current_control],
    78→            attributes => $attributes
    79→        );
    80→        $graph->add_node($constant);
    81→        return $constant;
    82→    }
    83→
    84→    # Create Return node
    85→    # If $control is undef, uses current_control. Otherwise uses provided control.
    86→    method build_return_node($value_node, $control = undef) {
    87→        # Debug: check what we received
    88→        my $ref_type = ref($value_node) || 'SCALAR';
    89→        my $prefix = substr($ref_type, 0, 15);
    90→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
    91→        unless ($ref_type && $is_node) {
    92→            warn "build_return_node received non-node: $ref_type\n";
    93→            return undef;
    94→        }
    95→
    96→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    97→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    98→
    99→        my $node_id = $self->next_node_id();
   100→        my $empty_attrs = {};
   101→        my $return = Chalk::IR::Node->new(
   102→            id => $node_id,
   103→            op => 'Return',
   104→            inputs => [$ctrl, $value_node->id],
   105→            attributes => $empty_attrs
   106→        );
   107→        $graph->add_node($return);
   108→        return $return;
   109→    }
   110→
   111→    # Set control input for an existing node
   112→    method set_node_control($node, $control_id) {
   113→        my $inputs = $node->inputs;
   114→        $inputs->[0] = $control_id;  # Control is always first input
   115→    }
   116→
   117→    # Create arithmetic operation nodes
   118→    method build_add_node($left_node, $right_node) {
   119→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   120→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   121→        my $attributes = {
   122→            left => $left_ref,
   123→            right => $right_ref
   124→        };
   125→        my $node_id = $self->next_node_id();
   126→        my $add = Chalk::IR::Node->new(
   127→            id => $node_id,
   128→            op => 'Add',
   129→            inputs => [$current_control, $left_node->id, $right_node->id],
   130→            attributes => $attributes,
   131→            derivation_id => $current_derivation_id,
   132→        );
   133→        $graph->add_node($add);
   134→        return $add;
   135→    }
   136→
   137→    method build_multiply_node($left_node, $right_node) {
   138→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   139→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   140→        my $attributes = {
   141→            left => $left_ref,
   142→            right => $right_ref
   143→        };
   144→        my $node_id = $self->next_node_id();
   145→        my $mul = Chalk::IR::Node->new(
   146→            id => $node_id,
   147→            op => 'Multiply',
   148→            inputs => [$current_control, $left_node->id, $right_node->id],
   149→            attributes => $attributes,
   150→            derivation_id => $current_derivation_id,
   151→        );
   152→        $graph->add_node($mul);
   153→        return $mul;
   154→    }
   155→
   156→    method build_sub_node($left_node, $right_node) {
   157→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   158→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   159→        my $attributes = {
   160→            left => $left_ref,
   161→            right => $right_ref
   162→        };
   163→        my $node_id = $self->next_node_id();
   164→        my $sub = Chalk::IR::Node->new(
   165→            id => $node_id,
   166→            op => 'Sub',
   167→            inputs => [$current_control, $left_node->id, $right_node->id],
   168→            attributes => $attributes
   169→        );
   170→        $graph->add_node($sub);
   171→        return $sub;
   172→    }
   173→
   174→    method build_divide_node($left_node, $right_node) {
   175→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   176→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   177→        my $attributes = {
   178→            left => $left_ref,
   179→            right => $right_ref
   180→        };
   181→        my $node_id = $self->next_node_id();
   182→        my $div = Chalk::IR::Node->new(
   183→            id => $node_id,
   184→            op => 'Div',
   185→            inputs => [$current_control, $left_node->id, $right_node->id],
   186→            attributes => $attributes
   187→        );
   188→        $graph->add_node($div);
   189→        return $div;
   190→    }
   191→
   192→    # Create Store node (variable assignment)
   193→    method build_store_node($var_name, $value_node, $control = undef) {
   194→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   195→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   196→
   197→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
   198→        my $attributes = {
   199→            name => $var_name,
   200→            value => $value_ref
   201→        };
   202→        my $node_id = $self->next_node_id();
   203→        my $store = Chalk::IR::Node->new(
   204→            id => $node_id,
   205→            op => 'Store',
   206→            inputs => [$ctrl, $value_node->id],
   207→            attributes => $attributes
   208→        );
   209→        $graph->add_node($store);
   210→        $scope->define($var_name, $store->id);
   211→        return $store;
   212→    }
   213→
   214→    # Create Load node (variable read)
   215→    method build_load_node($var_name) {
   216→        my $node_id = $scope->lookup($var_name);
   217→        return undef unless $node_id;
   218→
   219→        # Check if this is a Proj node (parameter) - if so, return it directly
   220→        my $node = $graph->nodes->{$node_id};
   221→        if ($node && $node->op eq 'Proj') {
   222→            # Parameter: return the Proj node directly
   223→            return $node;
   224→        }
   225→
   226→        # Regular variable: create Load node from Store
   227→        my $attributes = {
   228→            name => $var_name,
   229→            store_id => $node_id
   230→        };
   231→        my $load_id = $self->next_node_id();
   232→        my $load = Chalk::IR::Node->new(
   233→            id => $load_id,
   234→            op => 'Load',
   235→            inputs => [$current_control, $node_id],
   236→            attributes => $attributes
   237→        );
   238→        $graph->add_node($load);
   239→        return $load;
   240→    }
   241→
   242→    # Create Proj node (projection from MultiNode like Start)
   243→    method build_proj_node($source_node, $index, $label) {
   244→        my $attributes = {
   245→            index => $index,
   246→            label => $label
   247→        };
   248→        my $node_id = $self->next_node_id();
   249→        my $proj = Chalk::IR::Node->new(
   250→            id => $node_id,
   251→            op => 'Proj',
   252→            inputs => [$source_node->id],
   253→            attributes => $attributes
   254→        );
   255→        $graph->add_node($proj);
   256→        return $proj;
   257→    }
   258→
   259→    # Comparison nodes
   260→    method build_greater_node($left_node, $right_node) {
   261→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   262→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   263→        my $attributes = {
   264→            left => $left_ref,
   265→            right => $right_ref
   266→        };
   267→        my $node_id = $self->next_node_id();
   268→        my $cmp = Chalk::IR::Node->new(
   269→            id => $node_id,
   270→            op => 'Greater',
   271→            inputs => [$current_control, $left_node->id, $right_node->id],
   272→            attributes => $attributes
   273→        );
   274→        $graph->add_node($cmp);
   275→        return $cmp;
   276→    }
   277→
   278→    method build_less_node($left_node, $right_node) {
   279→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   280→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   281→        my $attributes = {
   282→            left => $left_ref,
   283→            right => $right_ref
   284→        };
   285→        my $node_id = $self->next_node_id();
   286→        my $cmp = Chalk::IR::Node->new(
   287→            id => $node_id,
   288→            op => 'Less',
   289→            inputs => [$current_control, $left_node->id, $right_node->id],
   290→            attributes => $attributes
   291→        );
   292→        $graph->add_node($cmp);
   293→        return $cmp;
   294→    }
   295→
   296→    method build_equal_node($left_node, $right_node) {
   297→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   298→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   299→        my $attributes = {
   300→            left => $left_ref,
   301→            right => $right_ref
   302→        };
   303→        my $node_id = $self->next_node_id();
   304→        my $cmp = Chalk::IR::Node->new(
   305→            id => $node_id,
   306→            op => 'Equal',
   307→            inputs => [$current_control, $left_node->id, $right_node->id],
   308→            attributes => $attributes
   309→        );
   310→        $graph->add_node($cmp);
   311→        return $cmp;
   312→    }
   313→
   314→    # Control flow nodes
   315→    method build_if_node($condition_node) {
   316→        my $condition_ref = { op => 'NodeRef', node_id => $condition_node->id };
   317→        my $attributes = { condition => $condition_ref };
   318→        my $node_id = $self->next_node_id();
   319→        my $if_node = Chalk::IR::Node->new(
   320→            id => $node_id,
   321→            op => 'If',
   322→            inputs => [$current_control, $condition_node->id],
   323→            attributes => $attributes
   324→        );
   325→        $graph->add_node($if_node);
   326→        return $if_node;
   327→    }
   328→
   329→    method build_if_true_node($if_node) {
   330→        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
   331→        return $if_true;
   332→    }
   333→
   334→    method build_if_false_node($if_node) {
   335→        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
   336→        return $if_false;
   337→    }
   338→
   339→    method build_region_node(@control_inputs) {
   340→        my $empty_attrs = {};
   341→        my $node_id = $self->next_node_id();
   342→        my $region = Chalk::IR::Node->new(
   343→            id => $node_id,
   344→            op => 'Region',
   345→            inputs => \@control_inputs,
   346→            attributes => $empty_attrs
   347→        );
   348→        $graph->add_node($region);
   349→        return $region;
   350→    }
   351→
   352→    method build_phi_node($region_node, @value_inputs) {
   353→        my $empty_attrs = {};
   354→        my $node_id = $self->next_node_id();
   355→        my $phi = Chalk::IR::Node->new(
   356→            id => $node_id,
   357→            op => 'Phi',
   358→            inputs => [$region_node->id, @value_inputs],
   359→            attributes => $empty_attrs
   360→        );
   361→        $graph->add_node($phi);
   362→        return $phi;
   363→    }
   364→
   365→    # Loop control flow nodes
   366→    method build_loop_node($entry_control = undef) {
   367→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   368→        my $empty_attrs = {};
   369→        my $node_id = $self->next_node_id();
   370→        my $loop = Chalk::IR::Node->new(
   371→            id => $node_id,
   372→            op => 'Loop',
   373→            inputs => [$ctrl],  # Entry control; backedge added later
   374→            attributes => $empty_attrs
   375→        );
   376→        $graph->add_node($loop);
   377→        return $loop;
   378→    }
   379→
   380→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   381→        # Loop phi starts with control and initial value
   382→        # Loop value added later (lazy phi pattern)
   383→        my @inputs = ($loop_node->id, $initial_value);
   384→        push @inputs, $loop_value if defined $loop_value;
   385→
   386→        my $empty_attrs = {};
   387→        my $node_id = $self->next_node_id();
   388→        my $phi = Chalk::IR::Node->new(
   389→            id => $node_id,
   390→            op => 'Phi',
   391→            inputs => \@inputs,
   392→            attributes => $empty_attrs
   393→        );
   394→        $graph->add_node($phi);
   395→        return $phi;
   396→    }
