   398→    # Function call nodes
   399→    method build_call_node($function_name, @arg_nodes) {
   400→        # Call: control, memory, arguments...
   401→        # For now, use current_control for both control and memory
   402→        my $attributes = { function => $function_name };
   403→        my $node_id = $self->next_node_id();
   404→        my $call = Chalk::IR::Node->new(
   405→            id => $node_id,
   406→            op => 'Call',
   407→            inputs => [$current_control, $current_control, map { $_->id } @arg_nodes],
   408→            attributes => $attributes
   409→        );
   410→        $graph->add_node($call);
   411→        return $call;
   412→    }
