   429→    method is_tracking_loop() {
   430→        return $loop_tracking_active;
   431→    }
   432→
   433→    method loop_entry_scope() {
   434→        return $loop_entry_scope;
   435→    }
   436→
   437→    method generate_loop_phi_nodes($loop_node) {
   438→        # Generate phi nodes for all variables modified within the loop
   439→        return {} unless $loop_tracking_active;
   440→        return {} unless defined $loop_entry_scope;
   441→
   442→        # Capture current (loop-end) values before creating phis
   443→        my $loop_end_scope = $scope->snapshot_bindings();
   444→
   445→        # Find which variables were modified in the loop
   446→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   447→
   448→        # Generate a phi node for each modified variable
   449→        my %phis = ();
   450→        for my $var (@modified_vars) {
   451→            my $initial_value = $loop_entry_scope->{$var};
   452→            my $loop_value = $loop_end_scope->{$var};
   453→
   454→            # Create phi with initial value; backedge added later
   455→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   456→            $phis{$var} = $phi;
   457→
   458→            # Update scope to use phi node for this variable
   459→            # This ensures uses after the loop see the phi
   460→            $scope->define($var, $phi->id);
   461→        }
   462→
   463→        return \%phis;
   464→    }
