        # Check if this is a Proj node (parameter) - if so, return it directly
        my $node = $graph->nodes->{$node_id};
        if ($node && $node->op eq 'Proj') {
            # Parameter: return the Proj node directly
            return $node;
        }

        # Regular variable: create Load node from Store
        my $attributes = {
            name => $var_name,
            store_id => $node_id
