     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→    field $current_derivation_id :reader;  # Current derivation ID for tagging nodes
    17→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    18→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    19→
    20→    ADJUST {
    21→        $graph = Chalk::IR::Graph->new();
    22→        $scope = Chalk::IR::Scope->new();
    23→    }
    24→
    25→    # Generate unique node ID
    26→    method next_node_id() {
    27→        my $id = "node_$node_counter";
    28→        $node_counter++;
    29→        return $id;
    30→    }
    31→
    32→    # Set current control flow node
    33→    method set_control($ctrl) {
    34→        $current_control = $ctrl;
    35→    }
    36→
    37→    # Set current derivation ID for tagging nodes
    38→    method set_derivation_id($deriv_id) {
    39→        $current_derivation_id = $deriv_id;
    40→    }
    41→
    42→    # Create Start node for a function/method
    43→    method build_start_node($function_name = 'main', $params = undef) {
    44→        $params //= [];
    45→        my $node_id = $self->next_node_id();
    46→        my $empty_inputs = [];
    47→        my $attributes = { function => $function_name, params => $params };
    48→        my $start = Chalk::IR::Node->new(
    49→            id            => $node_id,
    50→            op            => 'Start',
    51→            inputs        => $empty_inputs,
    52→            attributes    => $attributes,
    53→            derivation_id => $current_derivation_id,
    54→        );
    55→        $graph->add_node($start);
    56→        $self->set_control($start->id);
    57→
    58→        # Create Proj nodes for each parameter and register in scope
    59→        my $param_count = scalar($params->@*);
    60→        for my $i (0..($param_count - 1)) {
    61→            my $param_name = $params->[$i];
    62→            my $proj = $self->build_proj_node($start, $i, $param_name);
    63→            # Register parameter Proj in scope so lookups return it directly
    64→            $scope->define($param_name, $proj->id);
    65→        }
    66→
    67→        return $start;
    68→    }
    69→
    70→    # Create Constant node
    71→    method build_constant_node($value, $type = 'Int') {
    72→        my $node_id = $self->next_node_id();
    73→        my $attributes = { value => $value, type => $type };
    74→        my $constant = Chalk::IR::Node->new(
    75→            id => $node_id,
    76→            op => 'Constant',
    77→            inputs => [$current_control],
    78→            attributes => $attributes
    79→        );
    80→        $graph->add_node($constant);
    81→        return $constant;
    82→    }
    83→
    84→    # Create Return node
    85→    # If $control is undef, uses current_control. Otherwise uses provided control.
    86→    method build_return_node($value_node, $control = undef) {
    87→        # Debug: check what we received
    88→        my $ref_type = ref($value_node) || 'SCALAR';
    89→        my $prefix = substr($ref_type, 0, 15);
    90→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
    91→        unless ($ref_type && $is_node) {
    92→            warn "build_return_node received non-node: $ref_type\n";
    93→            return undef;
    94→        }
    95→
    96→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    97→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    98→
    99→        my $node_id = $self->next_node_id();
   100→        my $empty_attrs = {};
   101→        my $return = Chalk::IR::Node->new(
   102→            id => $node_id,
   103→            op => 'Return',
   104→            inputs => [$ctrl, $value_node->id],
   105→            attributes => $empty_attrs
   106→        );
   107→        $graph->add_node($return);
   108→        return $return;
   109→    }
   110→
   111→    # Set control input for an existing node
   112→    method set_node_control($node, $control_id) {
   113→        my $inputs = $node->inputs;
   114→        $inputs->[0] = $control_id;  # Control is always first input
   115→    }
   116→
   117→    # Create arithmetic operation nodes
   118→    method build_add_node($left_node, $right_node) {
   119→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   120→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   121→        my $attributes = {
   122→            left => $left_ref,
   123→            right => $right_ref
   124→        };
   125→        my $node_id = $self->next_node_id();
   126→        my $add = Chalk::IR::Node->new(
   127→            id => $node_id,
   128→            op => 'Add',
   129→            inputs => [$current_control, $left_node->id, $right_node->id],
   130→            attributes => $attributes
   131→        );
   132→        $graph->add_node($add);
   133→        return $add;
   134→    }
   135→
   136→    method build_multiply_node($left_node, $right_node) {
   137→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   138→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   139→        my $attributes = {
   140→            left => $left_ref,
   141→            right => $right_ref
   142→        };
   143→        my $node_id = $self->next_node_id();
   144→        my $mul = Chalk::IR::Node->new(
   145→            id => $node_id,
   146→            op => 'Multiply',
   147→            inputs => [$current_control, $left_node->id, $right_node->id],
   148→            attributes => $attributes
   149→        );
   150→        $graph->add_node($mul);
   151→        return $mul;
   152→    }
   153→
   154→    method build_sub_node($left_node, $right_node) {
   155→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   156→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   157→        my $attributes = {
   158→            left => $left_ref,
   159→            right => $right_ref
   160→        };
   161→        my $node_id = $self->next_node_id();
   162→        my $sub = Chalk::IR::Node->new(
   163→            id => $node_id,
   164→            op => 'Sub',
   165→            inputs => [$current_control, $left_node->id, $right_node->id],
   166→            attributes => $attributes
   167→        );
   168→        $graph->add_node($sub);
   169→        return $sub;
   170→    }
   171→
   172→    method build_divide_node($left_node, $right_node) {
   173→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   174→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   175→        my $attributes = {
   176→            left => $left_ref,
   177→            right => $right_ref
   178→        };
   179→        my $node_id = $self->next_node_id();
   180→        my $div = Chalk::IR::Node->new(
   181→            id => $node_id,
   182→            op => 'Div',
   183→            inputs => [$current_control, $left_node->id, $right_node->id],
   184→            attributes => $attributes
   185→        );
   186→        $graph->add_node($div);
   187→        return $div;
   188→    }
   189→
   190→    # Create Store node (variable assignment)
   191→    method build_store_node($var_name, $value_node, $control = undef) {
   192→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   193→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   194→
   195→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
   196→        my $attributes = {
   197→            name => $var_name,
   198→            value => $value_ref
   199→        };
   200→        my $node_id = $self->next_node_id();
   201→        my $store = Chalk::IR::Node->new(
   202→            id => $node_id,
   203→            op => 'Store',
   204→            inputs => [$ctrl, $value_node->id],
   205→            attributes => $attributes
   206→        );
   207→        $graph->add_node($store);
   208→        $scope->define($var_name, $store->id);
   209→        return $store;
   210→    }
   211→
   212→    # Create Load node (variable read)
   213→    method build_load_node($var_name) {
   214→        my $node_id = $scope->lookup($var_name);
   215→        return undef unless $node_id;
   216→
   217→        # Check if this is a Proj node (parameter) - if so, return it directly
   218→        my $node = $graph->nodes->{$node_id};
   219→        if ($node && $node->op eq 'Proj') {
   220→            # Parameter: return the Proj node directly
   221→            return $node;
   222→        }
   223→
   224→        # Regular variable: create Load node from Store
   225→        my $attributes = {
   226→            name => $var_name,
   227→            store_id => $node_id
   228→        };
   229→        my $load_id = $self->next_node_id();
   230→        my $load = Chalk::IR::Node->new(
   231→            id => $load_id,
   232→            op => 'Load',
   233→            inputs => [$current_control, $node_id],
   234→            attributes => $attributes
   235→        );
   236→        $graph->add_node($load);
   237→        return $load;
   238→    }
   239→
   240→    # Create Proj node (projection from MultiNode like Start)
   241→    method build_proj_node($source_node, $index, $label) {
   242→        my $attributes = {
   243→            index => $index,
   244→            label => $label
   245→        };
   246→        my $node_id = $self->next_node_id();
   247→        my $proj = Chalk::IR::Node->new(
   248→            id => $node_id,
   249→            op => 'Proj',
   250→            inputs => [$source_node->id],
   251→            attributes => $attributes
   252→        );
   253→        $graph->add_node($proj);
   254→        return $proj;
   255→    }
   256→
   257→    # Comparison nodes
   258→    method build_greater_node($left_node, $right_node) {
   259→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   260→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   261→        my $attributes = {
   262→            left => $left_ref,
   263→            right => $right_ref
   264→        };
   265→        my $node_id = $self->next_node_id();
   266→        my $cmp = Chalk::IR::Node->new(
   267→            id => $node_id,
   268→            op => 'Greater',
   269→            inputs => [$current_control, $left_node->id, $right_node->id],
   270→            attributes => $attributes
   271→        );
   272→        $graph->add_node($cmp);
   273→        return $cmp;
   274→    }
   275→
   276→    method build_less_node($left_node, $right_node) {
   277→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   278→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   279→        my $attributes = {
   280→            left => $left_ref,
   281→            right => $right_ref
   282→        };
   283→        my $node_id = $self->next_node_id();
   284→        my $cmp = Chalk::IR::Node->new(
   285→            id => $node_id,
   286→            op => 'Less',
   287→            inputs => [$current_control, $left_node->id, $right_node->id],
   288→            attributes => $attributes
   289→        );
   290→        $graph->add_node($cmp);
   291→        return $cmp;
   292→    }
   293→
   294→    method build_equal_node($left_node, $right_node) {
   295→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   296→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   297→        my $attributes = {
   298→            left => $left_ref,
   299→            right => $right_ref
   300→        };
   301→        my $node_id = $self->next_node_id();
   302→        my $cmp = Chalk::IR::Node->new(
   303→            id => $node_id,
   304→            op => 'Equal',
   305→            inputs => [$current_control, $left_node->id, $right_node->id],
   306→            attributes => $attributes
   307→        );
   308→        $graph->add_node($cmp);
   309→        return $cmp;
   310→    }
   311→
   312→    # Control flow nodes
   313→    method build_if_node($condition_node) {
   314→        my $condition_ref = { op => 'NodeRef', node_id => $condition_node->id };
   315→        my $attributes = { condition => $condition_ref };
   316→        my $node_id = $self->next_node_id();
   317→        my $if_node = Chalk::IR::Node->new(
   318→            id => $node_id,
   319→            op => 'If',
   320→            inputs => [$current_control, $condition_node->id],
   321→            attributes => $attributes
   322→        );
   323→        $graph->add_node($if_node);
   324→        return $if_node;
   325→    }
   326→
   327→    method build_if_true_node($if_node) {
   328→        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
   329→        return $if_true;
   330→    }
   331→
   332→    method build_if_false_node($if_node) {
   333→        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
   334→        return $if_false;
   335→    }
   336→
   337→    method build_region_node(@control_inputs) {
   338→        my $empty_attrs = {};
   339→        my $node_id = $self->next_node_id();
   340→        my $region = Chalk::IR::Node->new(
   341→            id => $node_id,
   342→            op => 'Region',
   343→            inputs => \@control_inputs,
   344→            attributes => $empty_attrs
   345→        );
   346→        $graph->add_node($region);
   347→        return $region;
   348→    }
   349→
   350→    method build_phi_node($region_node, @value_inputs) {
   351→        my $empty_attrs = {};
   352→        my $node_id = $self->next_node_id();
   353→        my $phi = Chalk::IR::Node->new(
   354→            id => $node_id,
   355→            op => 'Phi',
   356→            inputs => [$region_node->id, @value_inputs],
   357→            attributes => $empty_attrs
   358→        );
   359→        $graph->add_node($phi);
   360→        return $phi;
   361→    }
   362→
   363→    # Loop control flow nodes
   364→    method build_loop_node($entry_control = undef) {
   365→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   366→        my $empty_attrs = {};
   367→        my $node_id = $self->next_node_id();
   368→        my $loop = Chalk::IR::Node->new(
   369→            id => $node_id,
   370→            op => 'Loop',
   371→            inputs => [$ctrl],  # Entry control; backedge added later
   372→            attributes => $empty_attrs
   373→        );
   374→        $graph->add_node($loop);
   375→        return $loop;
   376→    }
   377→
   378→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   379→        # Loop phi starts with control and initial value
   380→        # Loop value added later (lazy phi pattern)
   381→        my @inputs = ($loop_node->id, $initial_value);
   382→        push @inputs, $loop_value if defined $loop_value;
   383→
   384→        my $empty_attrs = {};
   385→        my $node_id = $self->next_node_id();
   386→        my $phi = Chalk::IR::Node->new(
   387→            id => $node_id,
   388→            op => 'Phi',
   389→            inputs => \@inputs,
   390→            attributes => $empty_attrs
   391→        );
   392→        $graph->add_node($phi);
   393→        return $phi;
   394→    }
   395→
   396→    # Function call nodes
   397→    method build_call_node($function_name, @arg_nodes) {
   398→        # Call: control, memory, arguments...
   399→        # For now, use current_control for both control and memory
   400→        my $attributes = { function => $function_name };
   401→        my $node_id = $self->next_node_id();
   402→        my $call = Chalk::IR::Node->new(
   403→            id => $node_id,
   404→            op => 'Call',
   405→            inputs => [$current_control, $current_control, map { $_->id } @arg_nodes],
   406→            attributes => $attributes
   407→        );
   408→        $graph->add_node($call);
   409→        return $call;
   410→    }
   411→
   412→    # Loop-carried dependency tracking methods
   413→    method begin_loop_tracking() {
   414→        # Start tracking loop-carried dependencies
   415→        $loop_entry_scope = $scope->snapshot_bindings();
   416→        $loop_tracking_active = 1;
   417→        return;
   418→    }
   419→
   420→    method end_loop_tracking() {
   421→        # End tracking and clean up
   422→        $loop_entry_scope = undef;
   423→        $loop_tracking_active = 0;
   424→        return;
   425→    }
   426→
   427→    method is_tracking_loop() {
   428→        return $loop_tracking_active;
   429→    }
   430→
   431→    method loop_entry_scope() {
   432→        return $loop_entry_scope;
   433→    }
   434→
   435→    method generate_loop_phi_nodes($loop_node) {
   436→        # Generate phi nodes for all variables modified within the loop
   437→        return {} unless $loop_tracking_active;
   438→        return {} unless defined $loop_entry_scope;
   439→
   440→        # Capture current (loop-end) values before creating phis
   441→        my $loop_end_scope = $scope->snapshot_bindings();
   442→
   443→        # Find which variables were modified in the loop
   444→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   445→
   446→        # Generate a phi node for each modified variable
   447→        my %phis = ();
   448→        for my $var (@modified_vars) {
   449→            my $initial_value = $loop_entry_scope->{$var};
   450→            my $loop_value = $loop_end_scope->{$var};
   451→
   452→            # Create phi with initial value; backedge added later
   453→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   454→            $phis{$var} = $phi;
   455→
   456→            # Update scope to use phi node for this variable
   457→            # This ensures uses after the loop see the phi
   458→            $scope->define($var, $phi->id);
   459→        }
   460→
   461→        return \%phis;
   462→    }
   463→
   464→    # Class and object support nodes (Issue #98 Phase 1)
   465→
   466→    method build_classdef_node($class_name, $fields) {
   467→        # Create ClassDef node for class definition
   468→        my $attributes = {
   469→            name => $class_name,
   470→            fields => $fields,
   471→        };
   472→        my $node_id = $self->next_node_id();
   473→        my $classdef = Chalk::IR::Node->new(
   474→            id => $node_id,
   475→            op => 'ClassDef',
   476→            inputs => [$current_control],
   477→            attributes => $attributes
   478→        );
   479→        $graph->add_node($classdef);
   480→        return $classdef;
   481→    }
   482→
   483→    method build_new_node($class_name, $field_values_hash) {
   484→        # Create New node for object instantiation
   485→        # $field_values_hash is a hashref mapping field names to node objects
   486→        my @input_nodes = ($current_control);
   487→        my %field_value_refs;
   488→
   489→        # Build field references from hash
