        my $node_id = $self->next_node_id();
        my $field_store = Chalk::IR::Node->new(
            id => $node_id,
            op => 'FieldStore',
            inputs => [$current_control, $object_node->id, $value_node->id],
            attributes => $attributes
        );
        $graph->add_node($field_store);
        return $field_store;
    }

