        # Create StrLength node for getting string length
        my $string_ref = { op => 'NodeRef', node_id => $string_node->id };

        my $attributes = {
            string => $string_ref
        };

        my $node_id = $self->next_node_id();
        my $str_length = Chalk::IR::Node->new(
            id => $node_id,
            op => 'StrLength',
            inputs => [$current_control, $string_node->id],
