        my $attributes = { function => $function_name };
        my $node_id = $self->next_node_id();
        my $call = Chalk::IR::Node->new(
            id => $node_id,
            op => 'Call',
            inputs => [$current_control, $current_control, map { $_->id } @arg_nodes],
            attributes => $attributes
        );
