);

my $proj = Chalk::IR::Node->new(
    id => $node_id,
    op => 'Proj',
    inputs => [$source_node->id],
    attributes => $attributes
);

my $cmp = Chalk::IR::Node->new(
    id => $node_id,
    op => 'Greater',
    inputs => [$current_control, $left_node->id, $right_node->id],
    attributes => $attributes
);

my $cmp = Chalk::IR::Node->new(
    id => $node_id,
    op => 'Less',
