     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→    field $current_derivation_id :reader;  # Current derivation ID for tagging nodes
    17→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    18→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    19→
    20→    ADJUST {
    21→        $graph = Chalk::IR::Graph->new();
    22→        $scope = Chalk::IR::Scope->new();
    23→    }
    24→
    25→    # Generate unique node ID
    26→    method next_node_id() {
    27→        my $id = "node_$node_counter";
    28→        $node_counter++;
    29→        return $id;
    30→    }
    31→
    32→    # Set current control flow node
    33→    method set_control($ctrl) {
    34→        $current_control = $ctrl;
    35→    }
    36→
    37→    # Set current derivation ID for tagging nodes
    38→    method set_derivation_id($deriv_id) {
    39→        $current_derivation_id = $deriv_id;
    40→    }
    41→
    42→    # Create Start node for a function/method
    43→    method build_start_node($function_name = 'main', $params = undef) {
    44→        $params //= [];
    45→        my $node_id = $self->next_node_id();
    46→        my $empty_inputs = [];
    47→        my $attributes = { function => $function_name, params => $params };
    48→        my $start = Chalk::IR::Node->new(
    49→            id            => $node_id,
    50→            op            => 'Start',
    51→            inputs        => $empty_inputs,
    52→            attributes    => $attributes,
    53→            derivation_id => $current_derivation_id,
    54→        );
    55→        $graph->add_node($start);
    56→        $self->set_control($start->id);
    57→
    58→        # Create Proj nodes for each parameter and register in scope
    59→        my $param_count = scalar($params->@*);
    60→        for my $i (0..($param_count - 1)) {
    61→            my $param_name = $params->[$i];
    62→            my $proj = $self->build_proj_node($start, $i, $param_name);
    63→            # Register parameter Proj in scope so lookups return it directly
    64→            $scope->define($param_name, $proj->id);
    65→        }
    66→
    67→        return $start;
    68→    }
    69→
    70→    # Create Constant node
    71→    method build_constant_node($value, $type = 'Int') {
    72→        my $node_id = $self->next_node_id();
    73→        my $attributes = { value => $value, type => $type };
    74→        my $constant = Chalk::IR::Node->new(
    75→            id => $node_id,
    76→            op => 'Constant',
    77→            inputs => [$current_control],
    78→            attributes => $attributes
    79→        );
    80→        $graph->add_node($constant);
    81→        return $constant;
    82→    }
    83→
    84→    # Create Return node
    85→    # If $control is undef, uses current_control. Otherwise uses provided control.
    86→    method build_return_node($value_node, $control = undef) {
    87→        # Debug: check what we received
    88→        my $ref_type = ref($value_node) || 'SCALAR';
    89→        my $prefix = substr($ref_type, 0, 15);
    90→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
    91→        unless ($ref_type && $is_node) {
    92→            warn "build_return_node received non-node: $ref_type\n";
    93→            return undef;
    94→        }
    95→
    96→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    97→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    98→
    99→        my $node_id = $self->next_node_id();
   100→        my $empty_attrs = {};
   101→        my $return = Chalk::IR::Node->new(
   102→            id => $node_id,
   103→            op => 'Return',
   104→            inputs => [$ctrl, $value_node->id],
   105→            attributes => $empty_attrs
   106→        );
   107→        $graph->add_node($return);
   108→        return $return;
   109→    }
   110→
   111→    # Set control input for an existing node
   112→    method set_node_control($node, $control_id) {
   113→        my $inputs = $node->inputs;
   114→        $inputs->[0] = $control_id;  # Control is always first input
   115→    }
   116→
   117→    # Create arithmetic operation nodes
   118→    method build_add_node($left_node, $right_node) {
   119→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   120→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   121→        my $attributes = {
   122→            left => $left_ref,
   123→            right => $right_ref
   124→        };
   125→        my $node_id = $self->next_node_id();
   126→        my $add = Chalk::IR::Node->new(
   127→            id => $node_id,
   128→            op => 'Add',
   129→            inputs => [$current_control, $left_node->id, $right_node->id],
   130→            attributes => $attributes,
   131→            derivation_id => $current_derivation_id,
   132→        );
   133→        $graph->add_node($add);
   134→        return $add;
   135→    }
   136→
   137→    method build_multiply_node($left_node, $right_node) {
   138→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   139→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   140→        my $attributes = {
   141→            left => $left_ref,
   142→            right => $right_ref
   143→        };
   144→        my $node_id = $self->next_node_id();
   145→        my $mul = Chalk::IR::Node->new(
   146→            id => $node_id,
   147→            op => 'Multiply',
   148→            inputs => [$current_control, $left_node->id, $right_node->id],
   149→            attributes => $attributes,
   150→            derivation_id => $current_derivation_id,
   151→        );
   152→        $graph->add_node($mul);
   153→        return $mul;
   154→    }
   155→
   156→    method build_sub_node($left_node, $right_node) {
   157→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   158→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   159→        my $attributes = {
   160→            left => $left_ref,
   161→            right => $right_ref
   162→        };
   163→        my $node_id = $self->next_node_id();
   164→        my $sub = Chalk::IR::Node->new(
   165→            id => $node_id,
   166→            op => 'Sub',
   167→            inputs => [$current_control, $left_node->id, $right_node->id],
   168→            attributes => $attributes,
   169→            derivation_id => $current_derivation_id,
   170→        );
   171→        $graph->add_node($sub);
   172→        return $sub;
   173→    }
   174→
   175→    method build_divide_node($left_node, $right_node) {
   176→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   177→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   178→        my $attributes = {
   179→            left => $left_ref,
   180→            right => $right_ref
   181→        };
   182→        my $node_id = $self->next_node_id();
   183→        my $div = Chalk::IR::Node->new(
   184→            id => $node_id,
   185→            op => 'Div',
   186→            inputs => [$current_control, $left_node->id, $right_node->id],
   187→            attributes => $attributes,
   188→            derivation_id => $current_derivation_id,
   189→        );
   190→        $graph->add_node($div);
   191→        return $div;
   192→    }
   193→
   194→    # Create Store node (variable assignment)
   195→    method build_store_node($var_name, $value_node, $control = undef) {
   196→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   197→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   198→
   199→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
   200→        my $attributes = {
   201→            name => $var_name,
   202→            value => $value_ref
   203→        };
   204→        my $node_id = $self->next_node_id();
   205→        my $store = Chalk::IR::Node->new(
   206→            id => $node_id,
   207→            op => 'Store',
   208→            inputs => [$ctrl, $value_node->id],
   209→            attributes => $attributes
   210→        );
   211→        $graph->add_node($store);
   212→        $scope->define($var_name, $store->id);
   213→        return $store;
   214→    }
   215→
   216→    # Create Load node (variable read)
   217→    method build_load_node($var_name) {
   218→        my $node_id = $scope->lookup($var_name);
   219→        return undef unless $node_id;
   220→
   221→        # Check if this is a Proj node (parameter) - if so, return it directly
   222→        my $node = $graph->nodes->{$node_id};
   223→        if ($node && $node->op eq 'Proj') {
   224→            # Parameter: return the Proj node directly
   225→            return $node;
   226→        }
   227→
   228→        # Regular variable: create Load node from Store
   229→        my $attributes = {
   230→            name => $var_name,
   231→            store_id => $node_id
   232→        };
   233→        my $load_id = $self->next_node_id();
   234→        my $load = Chalk::IR::Node->new(
   235→            id => $load_id,
   236→            op => 'Load',
   237→            inputs => [$current_control, $node_id],
   238→            attributes => $attributes
   239→        );
   240→        $graph->add_node($load);
   241→        return $load;
   242→    }
   243→
   244→    # Create Proj node (projection from MultiNode like Start)
   245→    method build_proj_node($source_node, $index, $label) {
   246→        my $attributes = {
   247→            index => $index,
   248→            label => $label
   249→        };
   250→        my $node_id = $self->next_node_id();
   251→        my $proj = Chalk::IR::Node->new(
   252→            id => $node_id,
   253→            op => 'Proj',
   254→            inputs => [$source_node->id],
   255→            attributes => $attributes
   256→        );
   257→        $graph->add_node($proj);
   258→        return $proj;
   259→    }
   260→
   261→    # Comparison nodes
   262→    method build_greater_node($left_node, $right_node) {
   263→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   264→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   265→        my $attributes = {
   266→            left => $left_ref,
   267→            right => $right_ref
   268→        };
   269→        my $node_id = $self->next_node_id();
   270→        my $cmp = Chalk::IR::Node->new(
   271→            id => $node_id,
   272→            op => 'Greater',
   273→            inputs => [$current_control, $left_node->id, $right_node->id],
   274→            attributes => $attributes
   275→        );
   276→        $graph->add_node($cmp);
   277→        return $cmp;
   278→    }
   279→
   280→    method build_less_node($left_node, $right_node) {
   281→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   282→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   283→        my $attributes = {
   284→            left => $left_ref,
   285→            right => $right_ref
   286→        };
   287→        my $node_id = $self->next_node_id();
   288→        my $cmp = Chalk::IR::Node->new(
   289→            id => $node_id,
   290→            op => 'Less',
   291→            inputs => [$current_control, $left_node->id, $right_node->id],
   292→            attributes => $attributes
   293→        );
   294→        $graph->add_node($cmp);
   295→        return $cmp;
   296→    }
   297→
   298→    method build_equal_node($left_node, $right_node) {
   299→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   300→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   301→        my $attributes = {
   302→            left => $left_ref,
   303→            right => $right_ref
   304→        };
   305→        my $node_id = $self->next_node_id();
   306→        my $cmp = Chalk::IR::Node->new(
   307→            id => $node_id,
   308→            op => 'Equal',
   309→            inputs => [$current_control, $left_node->id, $right_node->id],
   310→            attributes => $attributes
   311→        );
   312→        $graph->add_node($cmp);
   313→        return $cmp;
   314→    }
   315→
   316→    # Control flow nodes
   317→    method build_if_node($condition_node) {
   318→        my $condition_ref = { op => 'NodeRef', node_id => $condition_node->id };
   319→        my $attributes = { condition => $condition_ref };
   320→        my $node_id = $self->next_node_id();
   321→        my $if_node = Chalk::IR::Node->new(
   322→            id => $node_id,
   323→            op => 'If',
   324→            inputs => [$current_control, $condition_node->id],
   325→            attributes => $attributes
   326→        );
   327→        $graph->add_node($if_node);
   328→        return $if_node;
   329→    }
   330→
   331→    method build_if_true_node($if_node) {
   332→        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
   333→        return $if_true;
   334→    }
   335→
   336→    method build_if_false_node($if_node) {
   337→        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
   338→        return $if_false;
   339→    }
   340→
   341→    method build_region_node(@control_inputs) {
   342→        my $empty_attrs = {};
   343→        my $node_id = $self->next_node_id();
   344→        my $region = Chalk::IR::Node->new(
   345→            id => $node_id,
   346→            op => 'Region',
   347→            inputs => \@control_inputs,
   348→            attributes => $empty_attrs
   349→        );
   350→        $graph->add_node($region);
   351→        return $region;
   352→    }
   353→
   354→    method build_phi_node($region_node, @value_inputs) {
   355→        my $empty_attrs = {};
   356→        my $node_id = $self->next_node_id();
   357→        my $phi = Chalk::IR::Node->new(
   358→            id => $node_id,
   359→            op => 'Phi',
   360→            inputs => [$region_node->id, @value_inputs],
   361→            attributes => $empty_attrs
   362→        );
   363→        $graph->add_node($phi);
   364→        return $phi;
   365→    }
   366→
   367→    # Loop control flow nodes
   368→    method build_loop_node($entry_control = undef) {
   369→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   370→        my $empty_attrs = {};
   371→        my $node_id = $self->next_node_id();
   372→        my $loop = Chalk::IR::Node->new(
   373→            id => $node_id,
   374→            op => 'Loop',
   375→            inputs => [$ctrl],  # Entry control; backedge added later
   376→            attributes => $empty_attrs
   377→        );
   378→        $graph->add_node($loop);
   379→        return $loop;
   380→    }
   381→
   382→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   383→        # Loop phi starts with control and initial value
   384→        # Loop value added later (lazy phi pattern)
   385→        my @inputs = ($loop_node->id, $initial_value);
   386→        push @inputs, $loop_value if defined $loop_value;
   387→
   388→        my $empty_attrs = {};
   389→        my $node_id = $self->next_node_id();
   390→        my $phi = Chalk::IR::Node->new(
   391→            id => $node_id,
   392→            op => 'Phi',
   393→            inputs => \@inputs,
   394→            attributes => $empty_attrs
   395→        );
   396→        $graph->add_node($phi);
   397→        return $phi;
   398→    }
   399→
   400→    # Function call nodes
   401→    method build_call_node($function_name, @arg_nodes) {
   402→        # Call: control, memory, arguments...
   403→        # For now, use current_control for both control and memory
   404→        my $attributes = { function => $function_name };
   405→        my $node_id = $self->next_node_id();
   406→        my $call = Chalk::IR::Node->new(
   407→            id => $node_id,
   408→            op => 'Call',
   409→            inputs => [$current_control, $current_control, map { $_->id } @arg_nodes],
   410→            attributes => $attributes
   411→        );
   412→        $graph->add_node($call);
   413→        return $call;
   414→    }
   415→
   416→    # Loop-carried dependency tracking methods
   417→    method begin_loop_tracking() {
   418→        # Start tracking loop-carried dependencies
   419→        $loop_entry_scope = $scope->snapshot_bindings();
   420→        $loop_tracking_active = 1;
   421→        return;
   422→    }
   423→
   424→    method end_loop_tracking() {
   425→        # End tracking and clean up
   426→        $loop_entry_scope = undef;
   427→        $loop_tracking_active = 0;
   428→        return;
   429→    }
   430→
   431→    method is_tracking_loop() {
   432→        return $loop_tracking_active;
   433→    }
   434→
   435→    method loop_entry_scope() {
   436→        return $loop_entry_scope;
   437→    }
   438→
   439→    method generate_loop_phi_nodes($loop_node) {
   440→        # Generate phi nodes for all variables modified within the loop
   441→        return {} unless $loop_tracking_active;
   442→        return {} unless defined $loop_entry_scope;
   443→
   444→        # Capture current (loop-end) values before creating phis
   445→        my $loop_end_scope = $scope->snapshot_bindings();
   446→
   447→        # Find which variables were modified in the loop
   448→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   449→
   450→        # Generate a phi node for each modified variable
   451→        my %phis = ();
   452→        for my $var (@modified_vars) {
   453→            my $initial_value = $loop_entry_scope->{$var};
   454→            my $loop_value = $loop_end_scope->{$var};
   455→
   456→            # Create phi with initial value; backedge added later
   457→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   458→            $phis{$var} = $phi;
   459→
   460→            # Update scope to use phi node for this variable
   461→            # This ensures uses after the loop see the phi
   462→            $scope->define($var, $phi->id);
   463→        }
   464→
   465→        return \%phis;
   466→    }
   467→
   468→    # Class and object support nodes (Issue #98 Phase 1)
   469→
   470→    method build_classdef_node($class_name, $fields) {
   471→        # Create ClassDef node for class definition
   472→        my $attributes = {
   473→            name => $class_name,
   474→            fields => $fields,
   475→        };
   476→        my $node_id = $self->next_node_id();
   477→        my $classdef = Chalk::IR::Node->new(
   478→            id => $node_id,
   479→            op => 'ClassDef',
   480→            inputs => [$current_control],
   481→            attributes => $attributes
   482→        );
   483→        $graph->add_node($classdef);
   484→        return $classdef;
   485→    }
   486→
   487→    method build_new_node($class_name, $field_values_hash) {
   488→        # Create New node for object instantiation
   489→        # $field_values_hash is a hashref mapping field names to node objects
   490→        my @input_nodes = ($current_control);
   491→        my %field_value_refs;
   492→
   493→        # Build field references from hash
   494→        for my $field_name (sort( keys( $field_values_hash->%* ) )) {
   495→            my $value_node = $field_values_hash->{$field_name};
   496→            push @input_nodes, $value_node->id;
   497→            $field_value_refs{$field_name} = {
   498→                op => 'NodeRef',
   499→                node_id => $value_node->id
   500→            };
   501→        }
   502→
   503→        my $attributes = {
   504→            class => $class_name,
   505→            field_values => \%field_value_refs
   506→        };
   507→        my $node_id = $self->next_node_id();
   508→        my $new_obj = Chalk::IR::Node->new(
   509→            id => $node_id,
   510→            op => 'New',
   511→            inputs => \@input_nodes,
   512→            attributes => $attributes
   513→        );
   514→        $graph->add_node($new_obj);
   515→        return $new_obj;
   516→    }
   517→
   518→    method build_field_access_node($object_node, $field_name) {
   519→        # Create FieldAccess node for reading a field
   520→        my $object_ref = { op => 'NodeRef', node_id => $object_node->id };
   521→        my $attributes = {
   522→            field => $field_name,
   523→            object => $object_ref
   524→        };
   525→        my $node_id = $self->next_node_id();
   526→        my $field_access = Chalk::IR::Node->new(
   527→            id => $node_id,
   528→            op => 'FieldAccess',
   529→            inputs => [$current_control, $object_node->id],
   530→            attributes => $attributes
   531→        );
