   438→
   439→    method generate_loop_phi_nodes($loop_node) {
   440→        # Generate phi nodes for all variables modified within the loop
   441→        return {} unless $loop_tracking_active;
   442→        return {} unless defined $loop_entry_scope;
   443→
   444→        # Capture current (loop-end) values before creating phis
   445→        my $loop_end_scope = $scope->snapshot_bindings();
   446→
   447→        # Find which variables were modified in the loop
   448→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   449→
   450→        # Generate a phi node for each modified variable
   451→        my %phis = ();
   452→        for my $var (@modified_vars) {
   453→            my $initial_value = $loop_entry_scope->{$var};
   454→            my $loop_value = $loop_end_scope->{$var};
   455→
   456→            # Create phi with initial value; backedge added later
   457→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   458→            $phis{$var} = $phi;
   459→
   460→            # Update scope to use phi node for this variable
   461→            # This ensures uses after the loop see the phi
   462→            $scope->define($var, $phi->id);
   463→        }
   464→
   465→        return \%phis;
   466→    }
