   699→        my $key_ref = { op => 'NodeRef', node_id => $key_node->id };
   700→        my $attributes = {
   701→            hash => $hash_ref,
   702→            key => $key_ref
   703→        };
   704→        my $node_id = $self->next_node_id();
   705→        my $hash_exists = Chalk::IR::Node->new(
   706→            id => $node_id,
   707→            op => 'HashExists',
   708→            inputs => [$current_control, $hash_node->id, $key_node->id],
   709→            attributes => $attributes
   710→        );
   711→        $graph->add_node($hash_exists);
   712→        return $hash_exists;
   713→    }
   714→
   715→    method build_hash_keys_node($hash_node) {
   716→        # Create HashKeys node for getting all keys from hash
   717→        my $hash_ref = { op => 'NodeRef', node_id => $hash_node->id };
   718→        my $attributes = {
