     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→    field $current_derivation_id :reader;  # Current derivation ID for tagging nodes
    17→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    18→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    19→
    20→    ADJUST {
    21→        $graph = Chalk::IR::Graph->new();
    22→        $scope = Chalk::IR::Scope->new();
    23→    }
    24→
    25→    # Generate unique node ID
    26→    method next_node_id() {
    27→        my $id = "node_$node_counter";
    28→        $node_counter++;
    29→        return $id;
    30→    }
    31→
    32→    # Set current control flow node
    33→    method set_control($ctrl) {
    34→        $current_control = $ctrl;
    35→    }
    36→
    37→    # Set current derivation ID for tagging nodes
    38→    method set_derivation_id($deriv_id) {
    39→        $current_derivation_id = $deriv_id;
    40→    }
    41→
    42→    # Create Start node for a function/method
    43→    method build_start_node($function_name = 'main', $params = undef) {
    44→        $params //= [];
    45→        my $node_id = $self->next_node_id();
    46→        my $empty_inputs = [];
    47→        my $attributes = { function => $function_name, params => $params };
    48→        my $start = Chalk::IR::Node->new(
    49→            id            => $node_id,
    50→            op            => 'Start',
    51→            inputs        => $empty_inputs,
    52→            attributes    => $attributes,
    53→            derivation_id => $current_derivation_id,
    54→        );
    55→        $graph->add_node($start);
    56→        $self->set_control($start->id);
    57→
    58→        # Create Proj nodes for each parameter and register in scope
    59→        my $param_count = scalar($params->@*);
    60→        for my $i (0..($param_count - 1)) {
    61→            my $param_name = $params->[$i];
    62→            my $proj = $self->build_proj_node($start, $i, $param_name);
    63→            # Register parameter Proj in scope so lookups return it directly
    64→            $scope->define($param_name, $proj->id);
    65→        }
    66→
    67→        return $start;
    68→    }
    69→
    70→    # Create Constant node
    71→    method build_constant_node($value, $type = 'Int') {
    72→        my $node_id = $self->next_node_id();
    73→        my $attributes = { value => $value, type => $type };
    74→        my $constant = Chalk::IR::Node->new(
    75→            id            => $node_id,
    76→            op            => 'Constant',
    77→            inputs        => [$current_control],
    78→            attributes    => $attributes,
    79→            derivation_id => $current_derivation_id,
    80→        );
    81→        $graph->add_node($constant);
    82→        return $constant;
    83→    }
    84→
    85→    # Create Return node
    86→    # If $control is undef, uses current_control. Otherwise uses provided control.
    87→    method build_return_node($value_node, $control = undef) {
    88→        # Debug: check what we received
    89→        my $ref_type = ref($value_node) || 'SCALAR';
    90→        my $prefix = substr($ref_type, 0, 15);
    91→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
    92→        unless ($ref_type && $is_node) {
    93→            warn "build_return_node received non-node: $ref_type\n";
    94→            return undef;
    95→        }
    96→
    97→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    98→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    99→
   100→        my $node_id = $self->next_node_id();
   101→        my $empty_attrs = {};
   102→        my $return = Chalk::IR::Node->new(
   103→            id => $node_id,
   104→            op => 'Return',
   105→            inputs => [$ctrl, $value_node->id],
   106→            attributes => $empty_attrs
   107→        );
   108→        $graph->add_node($return);
   109→        return $return;
   110→    }
   111→
   112→    # Set control input for an existing node
   113→    method set_node_control($node, $control_id) {
   114→        my $inputs = $node->inputs;
   115→        $inputs->[0] = $control_id;  # Control is always first input
   116→    }
   117→
   118→    # Create arithmetic operation nodes
   119→    method build_add_node($left_node, $right_node) {
   120→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   121→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   122→        my $attributes = {
   123→            left => $left_ref,
