   440→
   441→    method generate_loop_phi_nodes($loop_node) {
   442→        # Generate phi nodes for all variables modified within the loop
   443→        return {} unless $loop_tracking_active;
   444→        return {} unless defined $loop_entry_scope;
   445→
   446→        # Capture current (loop-end) values before creating phis
   447→        my $loop_end_scope = $scope->snapshot_bindings();
   448→
   449→        # Find which variables were modified in the loop
   450→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   451→
   452→        # Generate a phi node for each modified variable
   453→        my %phis = ();
   454→        for my $var (@modified_vars) {
   455→            my $initial_value = $loop_entry_scope->{$var};
   456→            my $loop_value = $loop_end_scope->{$var};
   457→
   458→            # Create phi with initial value; backedge added later
   459→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   460→            $phis{$var} = $phi;
   461→
   462→            # Update scope to use phi node for this variable
   463→            # This ensures uses after the loop see the phi
   464→            $scope->define($var, $phi->id);
   465→        }
   466→
   467→        return \%phis;
   468→    }
