        # Create ArraySet node for setting array element by index
        my $array_ref = { op => 'NodeRef', node_id => $array_node->id };
        my $index_ref = { op => 'NodeRef', node_id => $index_node->id };
        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
        my $attributes = {
