# ABOUTME: Earley parser implementation with Leo optimization for Chalk
# ABOUTME: Provides EarleyItem, LeoItem, EarleyChart, and Parser classes
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Chalk::Semiring::Boolean;

class Chalk::EarleyItem {
    use overload '""' => 'key';

    field $start_pos :param :reader;
    field $rule      :param :reader;
    field $dot_pos   :param :reader;
    field $end_pos   :param :reader;
    field $rule_id = $rule->id;
    field @rhs     = $rule->rhs->@*;
    field $complete    :reader = $dot_pos >= scalar(@rhs);
    field $next_symbol :reader = $complete ? '' : $rhs[$dot_pos];
    field $key = "Earley|$start_pos|$rule_id|$dot_pos|$end_pos";

    method advance_dot() {
        Chalk::EarleyItem->new(
            start_pos => $start_pos,
            rule      => $rule,
            dot_pos   => $dot_pos + 1,
            end_pos   => $end_pos,
        );
    }

    method key(@args) { $key }
}

# Leo Items: Limited optimization for right-recursive grammar patterns
#
# This is a LIMITED implementation of Joop Leo's optimization (1991) for right-recursive
# grammars.  It creates "Leo items" only in DETERMINISTIC cases where:
# 1. Exactly one Earley item is waiting for the completed symbol
# 2. The waiting item will be complete after this one reduction
# 3. The rule is right-recursive (LHS appears as last RHS symbol)
#
# Why limited? Full Leo would create items even with multiple waiting items and maintain
# a hash lookup by (position, symbol). Our grammar has 41 right-recursive rules, but
# performance testing shows grammar complexity (960+ rules) is the main bottleneck,
# not right-recursion specifically. This limited implementation provides O(n) behavior
# for simple right-recursive chains (ArrowChain, StatementList) without the complexity
# of full Leo.
#
# See t/optimization/test-leo-items.t for verification tests.
# See issue #10 for detailed analysis and rationale.
class Chalk::LeoItem {
    use overload '""' => 'key';

    field $symbol    :param :reader;
    field $start_pos :param :reader;
    field $end_pos   :param :reader;
    field $top_item  :param :reader;
    field $rule      :reader = $top_item->rule;

    method complete()    { 1 }
    method next_symbol() { }

    method key(@args) {
        return "LEO:$symbol|$start_pos|$end_pos";
    }

}

class Chalk::EarleyChart {
    field $semiring :param;
    field %chart;
    field @by_end_pos;
    field %predicted;    # Track what we've predicted at each position
    field %completed;    # Track what we've completed
    field %waiting_for;  # Index: waiting_for{symbol}{pos} = [items waiting for symbol at pos]
    field %leo_waiting_for;  # Index: leo_waiting_for{symbol}{pos} = [Leo items waiting for symbol at pos]

    method add_item($earley_item) {
        $chart{ $earley_item->key } = $earley_item;
    }

    method get_element($key) { $chart{$key} }

    method add_element( $item, $element ) {
        my $key     = $item->key;
        my $current = $self->get_element($key);
        $chart{$key} = $current ? $current + $element : $element;

        my $end_pos = $item->end_pos;
        push( $by_end_pos[$end_pos]->@*, $item );

        # Index by what they're waiting for
        if ($item isa Chalk::LeoItem) {
            # Leo items are indexed by their symbol and end position
            my $symbol = $item->symbol;
            my $leo_end_pos = $item->end_pos;
            $leo_waiting_for{$symbol} //= {};
            my $leo_by_symbol = $leo_waiting_for{$symbol};
            $leo_by_symbol->{$leo_end_pos} //= [];
            my $leo_list = $leo_by_symbol->{$leo_end_pos};
            push( $leo_list->@*, $item );
        }
        elsif (!$item->complete) {
            # Regular items indexed by next_symbol
            my $next_sym = $item->next_symbol;
            if ($next_sym) {
                my $waiting_end_pos = $item->end_pos;
                $waiting_for{$next_sym} //= {};
                my $waiting_by_sym = $waiting_for{$next_sym};
                $waiting_by_sym->{$waiting_end_pos} //= [];
                my $waiting_list = $waiting_by_sym->{$waiting_end_pos};
                push( $waiting_list->@*, $item );
            }
        }

        return $chart{$key};
    }

    method items_ending_at($end_pos) {
        return $by_end_pos[$end_pos]->@* if $by_end_pos[$end_pos];
        return;
    }

    method items_waiting_for($symbol, $pos) {
        my $by_symbol = $waiting_for{$symbol};
        if ($by_symbol && exists($by_symbol->{$pos})) {
            return $by_symbol->{$pos}->@*;
        }
        return;
    }

    method leo_items_waiting_for($symbol, $pos) {
        my $by_symbol = $leo_waiting_for{$symbol};
        if ($by_symbol && exists($by_symbol->{$pos})) {
            return $by_symbol->{$pos}->@*;
        }
        return;
    }

    method has_item($item) {
        return exists( $chart{$item} );
    }

    method has_predicted( $nonterminal, $pos, $rule_id ) {
        return exists( $predicted{"$nonterminal|$pos|$rule_id"} );
    }

    method mark_predicted( $nonterminal, $pos, $rule_id ) {
        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
    }

    method has_completed($item) {
        return exists( $completed{$item} );
    }

    method mark_completed($item) {
        $completed{$item} = 1;
    }

    method goal_value( $start_symbol, $n ) {

        # Find all complete items that span [0,n] with LHS = start_symbol
        my $result = $semiring->add_id;

        my @items = $self->items_ending_at($n);

        for my $item (@items) {
            next unless $item->complete;
            next unless $item->start_pos == 0;
            next unless $item->rule->lhs eq $start_symbol;

            my $element = $self->get_element($item);
            if ($element) {
                $result = $result + $element;

                # Early termination for Boolean semiring: we only need to know
                # IF a parse exists, not enumerate ALL parses. This prevents
                # memory exhaustion when parsing highly ambiguous inputs like
                # the grammar file itself (which has exponentially many parses).
                # For other semirings (like Semantic), we need to accumulate ALL
                # parses to get the correct result.
                if ($semiring isa Chalk::Semiring::Boolean && $result != $semiring->add_id) {
                    return $result;
                }
            }
        }

        # Check if we found any valid parses
        return $result == $semiring->add_id ? undef : $result;
    }
}

class Chalk::Parser {
    field $semiring :param = Chalk::Semiring::Boolean->new();
    field $grammar :param;
    field $preprocess :param = [];  # Arrayref of preprocessor class names
    field $input_string;  # Store input string for semantic actions

    method parse_string($input) {
        $input_string = $input;  # Store for semantic actions
        # Apply preprocessors in sequence
        for my $preprocessor_class ($preprocess->@*) {
            next unless defined $preprocessor_class;

            # Load the preprocessor module
            my $file = $preprocessor_class;
            my $search = '::';
            my $replace = '/';
            my $pos = index($file, $search);
            while ($pos >= 0) {
                substr($file, $pos, length($search), $replace);
                $pos = index($file, $search, $pos + length($replace));
            }
            require "$file.pm";

            # Apply preprocessing
            my $preprocessor = $preprocessor_class->new(input => $input);
            $preprocessor->transform();
            $input = $preprocessor->output;
        }

        my $chart = Chalk::EarleyChart->new( semiring => $semiring );

       # Initialize chart by predicting all rules for start symbol at position 0
        my $start_symbol = $grammar->start_symbol;
        for my $rule ( $grammar->rules_for($start_symbol) ) {
            my $start_item = Chalk::EarleyItem->new(
                start_pos => 0,
                rule      => $rule,
                dot_pos   => 0,
                end_pos   => 0,
            );

            my $start_element = $semiring->init_element_from_rule($rule, 0, 0);
            $chart->add_element( $start_item, $start_element );
        }

        # Process positions from 0 to end of string
        my $pos             = 0;
        my $input_length    = length($input);
        my $last_active_pos = 0;

        # Store input_string for semantic actions
        $input_string = $input;

        while ( $pos <= $input_length ) {
            my @agenda_before = $chart->items_ending_at($pos);
            $self->process_position_string( $pos, $chart, $input );

            # Track the last position where we had active items
            if ( @agenda_before > 0 ) {
                $last_active_pos = $pos;
            }

            ++$pos;
        }

        my $result =
          $chart->goal_value( $grammar->start_symbol, $input_length );

        # Show where parsing actually stopped if it failed
        if ( !$result && $last_active_pos < $input_length ) {
            warn(
"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
                  . "%)\n" );
        }

        return $result;
    }

    method process_position_string( $pos, $chart, $input_string ) {
        my @agenda = $chart->items_ending_at($pos);

        my $item;
        while ( $item = shift(@agenda) ) {
            my $element = $chart->get_element($item);
            next unless defined($element);

            if ( $item->complete ) {
                $self->complete( $item, $element, $chart, \@agenda );
            }
            else {
                my $next_sym = $item->next_symbol;
                if (defined($next_sym)) {
                    if ($grammar->is_nonterminal($next_sym) ) {
                        $self->predict( $item, $next_sym, $chart, \@agenda );
                    }
                    else {
                        # Try to match terminal with lexeme support
                        my $pattern = $item->rule->terminal_to_regex($next_sym);
                        pos($input_string) = $pos;
                        my $match_pattern = qr/\G($pattern)/;
                        if ( $input_string =~ $match_pattern ) {
                            my $match_length = length($1);
                            $self->scan( $item, $element, $chart, $pos,
                                $match_length );
                        }

                        # Aycock-Horspool optimization for nullable terminals:
                        # If the terminal can match empty string, also advance dot
                        if (ref($next_sym) eq 'Regexp' && "" =~ $next_sym) {
                            my $advanced_item = Chalk::EarleyItem->new(
                                start_pos => $item->start_pos,
                                rule      => $item->rule,
                                dot_pos   => $item->dot_pos + 1,
                                end_pos   => $item->end_pos
                            );

                            unless ( $chart->has_item($advanced_item) ) {
                                $chart->add_element( $advanced_item, $element );
                                push( @agenda, $advanced_item );
                            }
                        }
                    }
                }
            }
        }
    }

    method complete( $completed_item, $completed_element, $chart, $agenda ) {

        # Check if we've already completed this item
        return if $chart->has_completed($completed_item);
        $chart->mark_completed($completed_item);

        my $lhs = $completed_item->rule->lhs;

        # For Semantic semiring, evaluate the completed rule
        # NOTE: We evaluate and set the focus, but keep the children so they can
        # be accessed by parent rules during their evaluation
        if ($semiring isa Chalk::Semiring::Semantic) {
            # IMPORTANT: Get the LATEST element from the chart, not the one passed in!
            # The element passed in might be stale if multiply operations happened
            my $latest_element = $chart->get_element($completed_item);
            if ($latest_element) {
                $completed_element = $latest_element;
            }

            my $ctx = $completed_element->context;

            # Create evaluation context using the existing derivation ID from predict()
            # All completions building up a single parse tree share the same derivation ID
            my $eval_ctx = Chalk::EvalContext->new(
                focus => $ctx->focus,
                children => $ctx->children,
                start_pos => $ctx->start_pos,
                end_pos => $ctx->end_pos,
                env => $ctx->env,
                grammar => $ctx->grammar,
                rule => $ctx->rule,
                forest => $ctx->forest
            );

            my $evaluated_value = $completed_item->rule->evaluate($eval_ctx);

            # Create new context with evaluated focus but preserve children
            my $new_ctx = Chalk::EvalContext->new(
                focus => $evaluated_value,
                children => $eval_ctx->children,
                start_pos => $eval_ctx->start_pos,
                end_pos => $eval_ctx->end_pos,
                env => $eval_ctx->env,
                grammar => $eval_ctx->grammar,
                rule => $eval_ctx->rule,
                forest => $eval_ctx->forest
            );

            # Update the completed element with evaluated context
            $completed_element = Chalk::Semiring::SemanticElement->new(
                value => 1,
                context => $new_ctx
            );

            # Update the chart with evaluated element so parent rules can access the evaluated focus
            # The element has both the evaluated focus AND the accumulated children
            $chart->add_element($completed_item, $completed_element);
        }

        # Use indexed lookups to get items waiting for this symbol
        # This avoids the expensive grep operations with isa checks
        my @waiting_for_lhs = $chart->items_waiting_for($lhs, $completed_item->start_pos);
        my @leo_waiting = $chart->leo_items_waiting_for($lhs, $completed_item->start_pos);

  # Check for deterministic reduction (only if no Leo items waiting)
  # Leo items are only for deterministic right-recursive chains where:
  # 1. Only one item is waiting for this LHS
  # 2. The waiting item will be complete after this reduction
  # 3. The rule is right-recursive
  #
  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
  # here, but performance testing shows left-recursion is already faster than
  # right-recursion in our Earley implementation, so it's not needed.
        if (   @waiting_for_lhs == 1
            && @leo_waiting == 0
            && $waiting_for_lhs[0]->rule->is_right_recursive
            && $waiting_for_lhs[0]->dot_pos ==
            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
        {
            my $waiting_item = $waiting_for_lhs[0];

            # Use completed item's end position
            my $leo = Chalk::LeoItem->new(
                symbol    => $lhs,
                start_pos => $waiting_item->start_pos,
                end_pos   => $completed_item->end_pos,
                top_item  => $waiting_item,
            );

            my $waiting_element = $chart->get_element($waiting_item);
            next unless $waiting_element;
            my $combined_element = $waiting_element * $completed_element;
            $chart->add_element( $leo, $combined_element );
            push( $agenda->@*, $leo );
            return;    # Skip normal completion
        }

        # Normal completion for regular items
        for my $waiting_item (@waiting_for_lhs) {

            my $waiting_element = $chart->get_element($waiting_item);
            next unless $waiting_element;

            # Semiring multiplication ⊗ combines sequential components
            my $combined_element = $waiting_element * $completed_element;

            my $new_item = Chalk::EarleyItem->new(
                start_pos => $waiting_item->start_pos,
                rule      => $waiting_item->rule,
                dot_pos   => $waiting_item->dot_pos + 1,
                end_pos   => $completed_item->end_pos
            );

            # Only add if not already in chart
            unless ( $chart->has_item($new_item) ) {
                $chart->add_element( $new_item, $combined_element );
                push( $agenda->@*, $new_item );
            }
        }

        # Handle Leo items waiting for this completion
        for my $leo_item (@leo_waiting) {

            # Unpack the Leo chain to get the original waiting item
            my $current = $leo_item->top_item;
            while ( $current isa Chalk::LeoItem ) {
                $current = $current->top_item;
            }

            # Now $current is the original EarleyItem at the bottom of the chain
            # Complete it with the current completed item
            my $waiting_element = $chart->get_element($leo_item);
            next unless $waiting_element;
            my $combined_element = $waiting_element * $completed_element;

            my $new_item = Chalk::EarleyItem->new(
                start_pos => $current->start_pos,
                rule      => $current->rule,
                dot_pos   => $current->dot_pos + 1,
                end_pos   => $completed_item->end_pos
            );

            # Only add if not already in chart
            unless ( $chart->has_item($new_item) ) {
                $chart->add_element( $new_item, $combined_element );
                push( $agenda->@*, $new_item );
            }
        }
    }

    method predict( $item, $nonterminal, $chart, $agenda ) {
        my $pos = $item->end_pos;

# Check if we've already predicted this nonterminal from this rule at this position
# Multiple rules can predict the same nonterminal, so we track by rule origin
        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );

        # For Semantic semiring, get parent's derivation ID so children inherit it
        my $parent_derivation_id = undef;
        if ($semiring isa Chalk::Semiring::Semantic) {
            my $parent_element = $chart->get_element($item);
            if ($parent_element && $parent_element->context) {
                $parent_derivation_id = $parent_element->context->env->{derivation_id};
            }
        }

        for my $rule ( $grammar->rules_for($nonterminal) ) {
            my $predicted_item = Chalk::EarleyItem->new(
                start_pos => $pos,
                rule      => $rule,
                dot_pos   => 0,
                end_pos   => $pos
            );

            # Only add if not already in chart
            unless ( $chart->has_item($predicted_item) ) {
                my $rule_element = $semiring->init_element_from_rule($rule, $pos, $pos, $parent_derivation_id);
                $chart->add_element( $predicted_item, $rule_element );
                push( $agenda->@*, $predicted_item );
            }
        }

        # Aycock-Horspool optimization: if the nonterminal is nullable,
        # we can also advance the dot past it immediately
        if ( $grammar->is_nullable($nonterminal) ) {
            my $advanced_item = Chalk::EarleyItem->new(
                start_pos => $item->start_pos,
                rule      => $item->rule,
                dot_pos   => $item->dot_pos + 1,
                end_pos   => $item->end_pos
            );

            # Only add if not already present
            unless ( $chart->has_item($advanced_item) ) {
                my $current_element = $chart->get_element($item);
                if ($current_element) {
                    $chart->add_element( $advanced_item, $current_element );
                    push( $agenda->@*, $advanced_item );
                }
            }
        }
    }

    method scan( $item, $element, $chart, $pos, $match_length ) {
        my $scanned_item = Chalk::EarleyItem->new(
            start_pos => $item->start_pos,
            rule      => $item->rule,
            dot_pos   => $item->dot_pos + 1,
            end_pos   => $pos + $match_length
        );

        # For Semantic semiring, extract the matched terminal string value
        # and multiply with current element to accumulate terminals in children
        my $scanned_element;
        if ($semiring isa Chalk::Semiring::Semantic) {
            # Extract the matched terminal value from input string
            my $matched_value = substr($input_string, $pos, $match_length);

            # Create a context with the terminal value as focus
            my $terminal_ctx = Chalk::EvalContext->new(
                focus => $matched_value,
                children => [],
                start_pos => $pos,
                end_pos => $pos + $match_length,
                env => $semiring->grammar->start_symbol,  # Use grammar
                grammar => $grammar,
                rule => $item->rule
            );

            my $terminal_element = Chalk::Semiring::SemanticElement->new(
                value => 1,
                context => $terminal_ctx
            );

            # Multiply current element with terminal to accumulate in children
            $scanned_element = $element * $terminal_element;
        } else {
            # All other semirings receive position updates during scan
            # Semirings can choose to use or ignore positions based on their needs
            $scanned_element = $semiring->init_element_from_rule(
                $item->rule,
                $scanned_item->start_pos,
                $scanned_item->end_pos
            );
        }

        $chart->add_element( $scanned_item, $scanned_element );
    }
}

1;

content.content:
title:	Implement Latent Type Inference and Checking in Semantic Actions
state:	OPEN
author:	perigrin
labels:	enhancement
comments:	0
assignees:	
projects:	
milestone:	
number:	74
--
## Context

After proving IR generation works (issue #71), we should add type checking directly into the semantic actions. Rather than building untyped IR and then validating it in a separate pass, we generate typed IR from the start using Perl's latent type system - types inferred from sigils, operations, and context.

The latent type system is documented at: https://gist.github.com/perigrin/c4780a7511ba1421e49a4a8b385aaa3d

**Key Principle:** Types are implicit but checkable. No type annotations required.

**Architecture:** Types are inferred and checked during IR node creation:

```
Parse → SPPF → Semantic Actions (with type inference) → Typed IR
```

This is a refactoring of the semantic actions from issue #71 to add type information.

## Goals

1. Add type inference to semantic actions during IR generation
2. Semantic elements carry both IR nodes and type information
3. Validate type consistency during IR node composition
4. Fail fast with clear errors when types are incompatible
5. Enable type-directed IR optimizations

## Type System Specification

### Complete Type Lattice (Chalk Subset)

Based on the formal specification in https://gist.github.com/perigrin/c4780a7511ba1421e49a4a8b385aaa3d, restricted to Chalk's supported Perl subset:

```
                        Any (⊤)
                          |
        +-----------------+------------------+
        |                 |                  |
     Scalar             List              Code
        |                 |
        |                 +------+------+
        |                        |      |
        |                     Array   Hash
        |
        +--------+--------+--------+
        |        |        |        |
      Undef   Boolean    Str      Ref
                          |        |
                         Num       +----+----+----+
                          |        |    |    |    |
                         Int    Object ScalarRef ArrayRef
                                      HashRef CodeRef


                        None (⊥)
```

**Note:** Chalk does not support:
- Glob or GlobRef types (Perl symbol table entries)
- DualVar type (scalar dual-typed values)

### Key Subtyping Chains

**Primary Scalar Chain:**
```
Int <: Num <: Str <: Scalar <: Any
```

**Why Num <: Str?** Because numbers can round-trip through string conversion without loss:
- `42 → "42" → 42` (preserves value)
- But `"hello" → 0 → "0"` (loses information, so not all Str are Num)

**Other Chains:**
```
Undef <: Scalar <: Any
Boolean <: Scalar <: Any

Object <: Ref <: Scalar <: Any
ScalarRef <: Ref <: Scalar <: Any
ArrayRef <: Ref <: Scalar <: Any
HashRef <: Ref <: Scalar <: Any
CodeRef <: Ref <: Scalar <: Any

Array <: List <: Any
Hash <: List <: Any

Code <: Any

None <: (everything)
```

### Type Membership Definition

A value `v` belongs to type `T` if and only if **both** conditions hold:

1. **Syntactic Preservation**: Converting `v` to type `T` and back produces observationally equivalent results without information loss (round-trip coercion test)

2. **Semantic Fulfillment**: `v` satisfies all operational contracts defined for type `T`, ensuring meaningful behavior under `T`'s operations

**Example:** The string `"NaN"` passes syntactic preservation (round-trips through numeric interpretation) but fails semantic fulfillment because IEEE NaN violates reflexivity (`NaN ≠ NaN`). Therefore `"NaN" ∉ Num`.

### Critical Coercion Rules

**Numeric Coercion (⇓^Num):**
- Numeric literals remain themselves: `42 → 42`
- Valid numeric strings parse: `"42" → 42`, `"3.14" → 3.14`
- Invalid strings become 0: `"hello" → 0`
- References coerce to memory addresses: `\$x → 0x7f8a...`

**String Coercion (⇓^Str):**
- Strings remain unchanged: `"hello" → "hello"`
- Numbers stringify: `42 → "42"`, `3.14 → "3.14"`
- References show type+address: `\$x → "SCALAR(0x...)"`, `\@arr → "ARRAY(0x...)"`

**Boolean Coercion (⇓^Bool):**
- `true/false` preserve themselves (Perl 5.36+)
- `0`, `''`, `undef` are falsy
- All other values are truthy

### Special Type Semantics

**Boolean vs. Primitive Boolean:** The type `Boolean` contains all truthy/falsy values. The predicate `is_bool()` tests membership in a narrower primitive subset `{true, false}` (Perl 5.36+). Values like `1`, `0`, `''` coerce to Boolean but are not primitive Boolean members.

**List as Ephemeral Type:** Represents transient sequences existing only during list-context evaluation. Array and Hash produce List values when evaluated in list context, making both `<: List` while maintaining their persistent container nature.

```perl
# List appears in:
my @arr = (1, 2, 3);        # List literal converts to Array
my %hash = (a => 1, b => 2); # List literal converts to Hash
my @nums = (1..10);          # Range produces List
my ($x, $y) = foo();        # foo() returns List
sub bar($a, $b) { ... }      # Parameters received as List
```

**Undef:** A distinct type representing undefined values. Coerces to `0` in numeric context, `""` in string context, and false in boolean context.

### Observational Equivalence (≡)

Two values are observationally equivalent when they produce identical results under all coercions that distinguish values in their domain, regardless of internal representation.

Example: Integer `42 ≡ String "42"` because both stringify identically and numify identically.

## Implementation Approach

### Phase 1: Type Representation

Create type system classes matching the formal specification (Chalk subset):

```perl
# lib/Chalk/Type.pm
class Chalk::Type {
    method is_compatible_with($other) { ... }
    method coerce_to($target) { ... }
    method merge_with($other) { ... }  # For phi nodes
    method round_trip_preserves($value) { ... }  # Syntactic preservation
    method satisfies_contract($value) { ... }    # Semantic fulfillment
}

# Universal and bottom types
class Chalk::Type::Any :isa(Chalk::Type) { }
class Chalk::Type::None :isa(Chalk::Type) { }

# Scalar hierarchy
class Chalk::Type::Scalar :isa(Chalk::Type) { }

class Chalk::Type::Undef :isa(Chalk::Type::Scalar) { }

class Chalk::Type::Boolean :isa(Chalk::Type::Scalar) {
    # All truthy/falsy values
    method is_primitive_bool($value) { ... }  # {true, false} subset
}

class Chalk::Type::Str :isa(Chalk::Type::Scalar) { }

# Num <: Str because numbers round-trip through strings
class Chalk::Type::Num :isa(Chalk::Type::Str) { }

# Int <: Num
class Chalk::Type::Int :isa(Chalk::Type::Num) { }

# References
class Chalk::Type::Ref :isa(Chalk::Type::Scalar) { }
class Chalk::Type::Object :isa(Chalk::Type::Ref) { }
class Chalk::Type::ScalarRef :isa(Chalk::Type::Ref) { }
class Chalk::Type::ArrayRef :isa(Chalk::Type::Ref) { }
class Chalk::Type::HashRef :isa(Chalk::Type::Ref) { }
class Chalk::Type::CodeRef :isa(Chalk::Type::Ref) { }

# Ephemeral List type
class Chalk::Type::List :isa(Chalk::Type) {
    # Exists during list-context evaluation
    # Converts to Array or Hash on assignment

    method convert_to_target($target_sigil) {
        return Chalk::Type::Array->new(element_type => Chalk::Type::Any->new())
            if $target_sigil eq '@';
        return Chalk::Type::Hash->new(value_type => Chalk::Type::Any->new())
            if $target_sigil eq '%';
        die "Cannot assign List to scalar variable";
    }
}

# Persistent containers (Array <: List, Hash <: List)
class Chalk::Type::Array :isa(Chalk::Type::List) {
    field $element_type :param :reader;
}

class Chalk::Type::Hash :isa(Chalk::Type::List) {
    field $value_type :param :reader;
}

# Top-level types
class Chalk::Type::Code :isa(Chalk::Type) { }
```

### Phase 2: Type Environment in Semantic Semiring

Extend the semantic semiring to track types:

```perl
# lib/Chalk/Semiring/Semantic.pm
class Chalk::Semiring::Semantic :isa(Chalk::Semiring) {
    field $ir_graph :reader;
    field $type_env :reader;  # NEW: Track variable types
    field $node_counter :reader = 0;

    method init_element_from_rule($rule, $start_pos, $end_pos) {
        # Infer type from rule
        my $type = $self->infer_type_from_rule($rule);

        # Create IR node
        my $ir_node = $self->create_ir_node($rule, $start_pos, $end_pos);

        # Return element with both IR and type
        return Chalk::Semiring::SemanticElement->new(
            ir_node => $ir_node,
            type => $type
        );
    }

    method infer_type_from_rule($rule) {
        # Variable declaration: $x, @arr, %hash
        if ($rule->lhs eq 'Variable') {
            return $self->infer_from_sigil($rule);
        }

        # Literals
        if ($rule->lhs eq 'IntegerLiteral') {
            return Chalk::Type::Int->new();
        }
        if ($rule->lhs eq 'NumberLiteral') {
            return Chalk::Type::Num->new();
        }
        if ($rule->lhs eq 'StringLiteral') {
            return Chalk::Type::Str->new();
        }
        if ($rule->lhs eq 'UndefLiteral') {
            return Chalk::Type::Undef->new();
        }

        # List literal (ephemeral until assigned)
        if ($rule->lhs eq 'ListLiteral') {
            return Chalk::Type::List->new();
        }

        # Range operator produces List
        if ($rule->lhs eq 'Range') {
            return Chalk::Type::List->new();
        }

        # Operations infer from context
        if ($rule->lhs eq 'Add') {
            return Chalk::Type::Num->new();  # Addition produces Num
        }
        if ($rule->lhs eq 'Concatenate') {
            return Chalk::Type::Str->new();  # Concat produces Str
        }

        # Default
        return Chalk::Type::Any->new();
    }

    method infer_from_sigil($rule) {
        my $sigil = $rule->rhs->[0];  # $, @, %

        return Chalk::Type::Scalar->new() if $sigil eq '$';
        return Chalk::Type::Array->new(
            element_type => Chalk::Type::Any->new()
        ) if $sigil eq '@';
        return Chalk::Type::Hash->new(
            value_type => Chalk::Type::Any->new()
        ) if $sigil eq '%';

        die "Unknown sigil: $sigil";
    }
}
```

### Phase 3: Type Checking with Round-Trip Preservation

Implement the formal type membership criteria:

```perl
# In Chalk::Type
method check_membership($value) {
    # Type membership requires BOTH:
    # 1. Syntactic preservation (round-trip)
    # 2. Semantic fulfillment (contracts)

    return $self->round_trip_preserves($value) &&
           $self->satisfies_contract($value);
}

# Example for Num type
class Chalk::Type::Num {
    method round_trip_preserves($value) {
        # Num → Str → Num should be observationally equivalent
        my $as_str = $value->to_string();
        my $back_to_num = $as_str->to_number();
        return $value ≡ $back_to_num;
    }

    method satisfies_contract($value) {
        # Must satisfy numeric contracts
        # e.g., reflexivity: $value == $value
        # This excludes NaN despite syntactic preservation
        return $value == $value;  # NaN fails this
    }
}
```

### Phase 4: Coercion Implementation

Implement the formal coercion rules:

```perl
# lib/Chalk/Type/Coercion.pm
class Chalk::Type::Coercion {
    # Numeric coercion: ⇓^Num
    method to_num($value, $source_type) {
        return $value if $source_type->isa('Chalk::Type::Num');

        if ($source_type->isa('Chalk::Type::Str')) {
            # Valid numeric strings parse
            return parse_number($value) if is_numeric_string($value);
            # Invalid strings → 0
            return 0;
        }

        if ($source_type->isa('Chalk::Type::Ref')) {
            # References → memory address
            return $value->address();
        }

        if ($source_type->isa('Chalk::Type::Undef')) {
            return 0;
        }

        die "Cannot coerce $source_type to Num";
    }

    # String coercion: ⇓^Str
    method to_str($value, $source_type) {
        return $value if $source_type->isa('Chalk::Type::Str');

        if ($source_type->isa('Chalk::Type::Num')) {
            return stringify($value);
        }

        if ($source_type->isa('Chalk::Type::Ref')) {
            my $type_name = $source_type->ref_type_name();
            return "$type_name(0x" . $value->address() . ")";
        }

        if ($source_type->isa('Chalk::Type::Undef')) {
            return "";
        }

        die "Cannot coerce $source_type to Str";
    }

    # Boolean coercion: ⇓^Bool
    method to_bool($value, $source_type) {
        if ($source_type->isa('Chalk::Type::Boolean')) {
            return $value;
        }

        # 0, '', undef are falsy
        return false if $value == 0 || $value eq '' || 
                       $source_type->isa('Chalk::Type::Undef');

        # All else truthy
        return true;
    }
}
```

### Phase 5: Built-in Function Signatures

```perl
# lib/Chalk/Builtins.pm
our %BUILTIN_SIGNATURES = (
    'length' => {
        params => [Chalk::Type::Str->new()],
        returns => Chalk::Type::Int->new(),
    },
    'push' => {
        params => [
            Chalk::Type::Array->new(element_type => Chalk::Type::Any->new()),
            Chalk::Type::Any->new(),
        ],
        returns => Chalk::Type::Int->new(),
    },
    'defined' => {
        params => [Chalk::Type::Any->new()],
        returns => Chalk::Type::Boolean->new(),
    },
    # ... more
);
```

## Example Type Checking

### Valid Code Examples

```perl
