     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→    field $current_derivation_id :reader;  # Current derivation ID for tagging nodes
    17→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    18→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    19→
    20→    ADJUST {
    21→        $graph = Chalk::IR::Graph->new();
    22→        $scope = Chalk::IR::Scope->new();
    23→    }
    24→
    25→    # Generate unique node ID
    26→    method next_node_id() {
    27→        my $id = "node_$node_counter";
    28→        $node_counter++;
    29→        return $id;
    30→    }
    31→
    32→    # Set current control flow node
    33→    method set_control($ctrl) {
    34→        $current_control = $ctrl;
    35→    }
    36→
    37→    # Set current derivation ID for tagging nodes
    38→    method set_derivation_id($deriv_id) {
    39→        $current_derivation_id = $deriv_id;
    40→    }
    41→
    42→    # Create Start node for a function/method
    43→    method build_start_node($function_name = 'main', $params = undef) {
    44→        $params //= [];
    45→        my $node_id = $self->next_node_id();
    46→        my $empty_inputs = [];
    47→        my $attributes = { function => $function_name, params => $params };
    48→        my $start = Chalk::IR::Node->new(
    49→            id            => $node_id,
    50→            op            => 'Start',
    51→            inputs        => $empty_inputs,
    52→            attributes    => $attributes,
    53→            derivation_id => $current_derivation_id,
    54→        );
    55→        $graph->add_node($start);
    56→        $self->set_control($start->id);
    57→
    58→        # Create Proj nodes for each parameter and register in scope
    59→        my $param_count = scalar($params->@*);
    60→        for my $i (0..($param_count - 1)) {
    61→            my $param_name = $params->[$i];
    62→            my $proj = $self->build_proj_node($start, $i, $param_name);
    63→            # Register parameter Proj in scope so lookups return it directly
    64→            $scope->define($param_name, $proj->id);
    65→        }
    66→
    67→        return $start;
    68→    }
    69→
    70→    # Create Constant node
    71→    method build_constant_node($value, $type = 'Int') {
    72→        my $node_id = $self->next_node_id();
    73→        my $attributes = { value => $value, type => $type };
    74→        my $constant = Chalk::IR::Node->new(
    75→            id            => $node_id,
    76→            op            => 'Constant',
    77→            inputs        => [$current_control],
    78→            attributes    => $attributes,
    79→            derivation_id => $current_derivation_id,
    80→        );
    81→        $graph->add_node($constant);
    82→        return $constant;
    83→    }
    84→
    85→    # Create Return node
    86→    # If $control is undef, uses current_control. Otherwise uses provided control.
    87→    method build_return_node($value_node, $control = undef) {
    88→        # Debug: check what we received
    89→        my $ref_type = ref($value_node) || 'SCALAR';
    90→        my $prefix = substr($ref_type, 0, 15);
    91→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
    92→        unless ($ref_type && $is_node) {
    93→            warn "build_return_node received non-node: $ref_type\n";
    94→            return undef;
    95→        }
    96→
    97→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    98→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    99→
   100→        my $node_id = $self->next_node_id();
   101→        my $empty_attrs = {};
   102→        my $return = Chalk::IR::Node->new(
   103→            id            => $node_id,
   104→            op            => 'Return',
   105→            inputs        => [$ctrl, $value_node->id],
   106→            attributes    => $empty_attrs,
   107→            derivation_id => $current_derivation_id,
   108→        );
   109→        $graph->add_node($return);
   110→        return $return;
   111→    }
   112→
   113→    # Set control input for an existing node
   114→    method set_node_control($node, $control_id) {
   115→        my $inputs = $node->inputs;
   116→        $inputs->[0] = $control_id;  # Control is always first input
   117→    }
   118→
   119→    # Create arithmetic operation nodes
   120→    method build_add_node($left_node, $right_node) {
   121→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   122→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   123→        my $attributes = {
   124→            left => $left_ref,
   125→            right => $right_ref
   126→        };
   127→        my $node_id = $self->next_node_id();
   128→        my $add = Chalk::IR::Node->new(
   129→            id => $node_id,
   130→            op => 'Add',
   131→            inputs => [$current_control, $left_node->id, $right_node->id],
   132→            attributes => $attributes,
   133→            derivation_id => $current_derivation_id,
   134→        );
   135→        $graph->add_node($add);
   136→        return $add;
   137→    }
   138→
   139→    method build_multiply_node($left_node, $right_node) {
   140→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   141→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   142→        my $attributes = {
   143→            left => $left_ref,
   144→            right => $right_ref
   145→        };
   146→        my $node_id = $self->next_node_id();
   147→        my $mul = Chalk::IR::Node->new(
   148→            id => $node_id,
   149→            op => 'Multiply',
   150→            inputs => [$current_control, $left_node->id, $right_node->id],
   151→            attributes => $attributes,
   152→            derivation_id => $current_derivation_id,
   153→        );
   154→        $graph->add_node($mul);
   155→        return $mul;
   156→    }
   157→
   158→    method build_sub_node($left_node, $right_node) {
   159→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   160→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   161→        my $attributes = {
   162→            left => $left_ref,
   163→            right => $right_ref
   164→        };
   165→        my $node_id = $self->next_node_id();
   166→        my $sub = Chalk::IR::Node->new(
   167→            id => $node_id,
   168→            op => 'Sub',
   169→            inputs => [$current_control, $left_node->id, $right_node->id],
   170→            attributes => $attributes,
   171→            derivation_id => $current_derivation_id,
   172→        );
   173→        $graph->add_node($sub);
   174→        return $sub;
   175→    }
   176→
   177→    method build_divide_node($left_node, $right_node) {
   178→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   179→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   180→        my $attributes = {
   181→            left => $left_ref,
   182→            right => $right_ref
   183→        };
   184→        my $node_id = $self->next_node_id();
   185→        my $div = Chalk::IR::Node->new(
   186→            id => $node_id,
   187→            op => 'Div',
   188→            inputs => [$current_control, $left_node->id, $right_node->id],
   189→            attributes => $attributes,
   190→            derivation_id => $current_derivation_id,
   191→        );
   192→        $graph->add_node($div);
   193→        return $div;
   194→    }
   195→
   196→    # Create Store node (variable assignment)
   197→    method build_store_node($var_name, $value_node, $control = undef) {
   198→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   199→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   200→
   201→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
   202→        my $attributes = {
   203→            name => $var_name,
   204→            value => $value_ref
   205→        };
   206→        my $node_id = $self->next_node_id();
   207→        my $store = Chalk::IR::Node->new(
   208→            id            => $node_id,
   209→            op            => 'Store',
   210→            inputs        => [$ctrl, $value_node->id],
   211→            attributes    => $attributes,
   212→            derivation_id => $current_derivation_id,
   213→        );
   214→        $graph->add_node($store);
   215→        $scope->define($var_name, $store->id);
   216→        return $store;
   217→    }
   218→
   219→    # Create Load node (variable read)
   220→    method build_load_node($var_name) {
   221→        my $node_id = $scope->lookup($var_name);
   222→        return undef unless $node_id;
   223→
   224→        # Check if this is a Proj node (parameter) - if so, return it directly
   225→        my $node = $graph->nodes->{$node_id};
   226→        if ($node && $node->op eq 'Proj') {
   227→            # Parameter: return the Proj node directly
   228→            return $node;
   229→        }
   230→
   231→        # Regular variable: create Load node from Store
   232→        my $attributes = {
   233→            name => $var_name,
   234→            store_id => $node_id
   235→        };
   236→        my $load_id = $self->next_node_id();
   237→        my $load = Chalk::IR::Node->new(
   238→            id            => $load_id,
   239→            op            => 'Load',
   240→            inputs        => [$current_control, $node_id],
   241→            attributes    => $attributes,
   242→            derivation_id => $current_derivation_id,
   243→        );
   244→        $graph->add_node($load);
   245→        return $load;
   246→    }
   247→
   248→    # Create Proj node (projection from MultiNode like Start)
   249→    method build_proj_node($source_node, $index, $label) {
   250→        my $attributes = {
   251→            index => $index,
   252→            label => $label
   253→        };
   254→        my $node_id = $self->next_node_id();
   255→        my $proj = Chalk::IR::Node->new(
   256→            id            => $node_id,
   257→            op            => 'Proj',
   258→            inputs        => [$source_node->id],
   259→            attributes    => $attributes,
   260→            derivation_id => $current_derivation_id,
   261→        );
   262→        $graph->add_node($proj);
   263→        return $proj;
