   452→
   453→    method generate_loop_phi_nodes($loop_node) {
   454→        # Generate phi nodes for all variables modified within the loop
   455→        return {} unless $loop_tracking_active;
   456→        return {} unless defined $loop_entry_scope;
   457→
   458→        # Capture current (loop-end) values before creating phis
   459→        my $loop_end_scope = $scope->snapshot_bindings();
   460→
   461→        # Find which variables were modified in the loop
   462→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   463→
   464→        # Generate a phi node for each modified variable
   465→        my %phis = ();
   466→        for my $var (@modified_vars) {
   467→            my $initial_value = $loop_entry_scope->{$var};
   468→            my $loop_value = $loop_end_scope->{$var};
   469→
   470→            # Create phi with initial value; backedge added later
   471→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   472→            $phis{$var} = $phi;
   473→
   474→            # Update scope to use phi node for this variable
   475→            # This ensures uses after the loop see the phi
   476→            $scope->define($var, $phi->id);
   477→        }
   478→
   479→        return \%phis;
   480→    }
