        );
        $graph->add_node($cmp);
        return $cmp;
    }

    method build_equal_node($left_node, $right_node) {
        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
        my $attributes = {
