    }

    # Hash operations (Issue #98 Phase 3)
    method build_hash_new_node() {
        # Create HashNew node for creating an empty hash
        my $node_id = $self->next_node_id();
        my $hash_new = Chalk::IR::Node->new(
            id => $node_id,
